BAT_THUAN_ALIAS_MAP = {'Thuần Càn': 'Càn Vi Thiên', 'Thuần Khôn': 'Khôn Vi Địa', 'Thuần Chấn': 'Chấn Vi Lôi', 'Thuần Tốn': 'Tốn Vi Phong', 'Thuần Khảm': 'Khảm Vi Thủy', 'Thuần Ly': 'Ly Vi Hỏa', 'Thuần Cấn': 'Cấn Vi Sơn', 'Thuần Đoài': 'Đoài Vi Trạch'}

DUNG_CUU_LUC = {'Càn Vi Thiên': {'title': 'Dụng Cửu (6 hào Dương cùng động)', 'zh': '见群龙无首，吉。', 'xiang_zh': '用九，天德不可为首也。', 'vn': '[ĐẠI CÁT] Kiến quần long vô thủ, Cát — Bầy rồng hiện ra không con nào tự nhận làm đầu; cương mà biết hóa nhu, không kiêu ngạo tranh quyền đứng mũi chịu sào thì đại cát vô cùng.'}, 'Khôn Vi Địa': {'title': 'Dụng Lục (6 hào Âm cùng động)', 'zh': '利永贞。', 'xiang_zh': '用六“永贞”，以大终也。', 'vn': '[CÁT BỀN VỮNG] Lợi vĩnh trinh — Sáu hào Âm hóa Dương cương kiện, giữ vững đạo chính bền bỉ lâu dài thì kết cục đại thành.'}}

ZHOUYI_64_FULL = {'Càn Vi Thiên': {'id': 1, 'vn_name': 'Càn Vi Thiên', 'zh_name': '乾', 'symbol': '䷀', 'binary': '111111', 'upper': 'Càn', 'lower': 'Càn', 'upper_el': 'Kim', 'lower_el': 'Kim', 'quai_tu_zh': '元亨利贞。', 'quai_tu_vn': 'Nguyên Hanh Lợi Trinh — Khởi đầu hanh thông, lợi ích chính đáng', 'thoan_truyen_zh': '大哉乾元，万物资始，乃统天。云行雨施，品物流形。大明终始，六位时成，时乘六龙以御天。乾道变化，各正性命，保合太和，乃利贞。首出庶物，万国咸宁。', 'dai_tuong_zh': '天行健，君子以自强不息。', 'dai_tuong_vn': 'Trời đi mạnh, quân tử tự cường không nghỉ', 'y_nghia_vn': 'Sức mạnh sáng tạo, cương kiện, lãnh đạo, cha', 'loi_khuyen_vn': 'Hành động mạnh mẽ, kiên trì, tự lực cánh sinh', 'cat_hung': 'ĐẠI CÁT', 'tap_quai_zh': '剛', 'tu_quai_zh': '有天地始', 'gaodao_zh': '乾卦纯阳至健，天之象也。元亨利贞四德：元为仁之原，亨为礼之和，利为义之和，贞为智之正。占得此卦，万事亨通，示人效法天德，自强不息。刚健中正，纯粹精也。君子法天健行，功德完备则获吉祥。问事利刚健进取，不可懈怠。', 'gaodao_en': "Pure Yang, the strongest. The four virtues: Yuan (origination), Heng (success), Li (benefit), Zhen (perseverance). This hexagram indicates supreme success through vigorous, ceaseless effort. The superior person models themselves on Heaven's movement, striving without rest. Benefits come through persistent, righteous action.", 'topics_vn': {'fortune': 'Đại cát. Mọi việc hanh thông nếu giữ tâm chính trực.', 'wish': 'Thành công lớn, nhưng không được kiêu ngạo.', 'love': 'Thuận lợi nhưng cần bớt cái tôi, người nam thường gia trưởng.', 'family': 'Nghiêm khắc nhưng hưng vượng.', 'sickness': 'Liên quan đến đầu, phổi. Bệnh dương khí quá vượng.', 'lost_item': 'Tìm ở nơi cao, hướng Tây Bắc. Đồ vật kim loại/tròn.', 'career': 'Thăng tiến, làm lãnh đạo, tự mình làm chủ.'}}, 'Khôn Vi Địa': {'id': 2, 'vn_name': 'Khôn Vi Địa', 'zh_name': '坤', 'symbol': '䷁', 'binary': '000000', 'upper': 'Khôn', 'lower': 'Khôn', 'upper_el': 'Thổ', 'lower_el': 'Thổ', 'quai_tu_zh': '元亨，利牝马之贞。君子有攸往，先迷，后得主，利。西南得朋，东北丧朋。安贞吉。', 'quai_tu_vn': 'Nguyên Hanh, lợi tẫn mã trinh — Đất rộng thuận theo trời', 'thoan_truyen_zh': '至哉坤元，万物资生，乃顺承天。坤厚载物，德合无疆；含弘光大，品物咸亨。“牝马”地类，行地无疆。柔顺利贞，君子攸行。先迷失道，后顺得常。“西南得朋”，乃与类行；“东北丧朋”，乃终有庆。安贞之吉，应地无疆。', 'dai_tuong_zh': '地势坤，君子以厚德载物。', 'dai_tuong_vn': 'Đất thuận chở, quân tử dày đức chở vật', 'y_nghia_vn': 'Nhu thuận, bao dung, nuôi dưỡng, mẹ, đất', 'loi_khuyen_vn': 'Nhẫn nại, thuận theo tự nhiên, không tranh đấu', 'cat_hung': 'CÁT', 'tap_quai_zh': '柔', 'tu_quai_zh': '有天地始', 'gaodao_zh': "坤卦象征柔顺包容，坤地纯阴。'坤元亨利牝马之贞'，柔顺成乾，坤以简能。厚德载物，中正广生。问事宜柔顺行事，厚德待人。", 'gaodao_en': "The Receptive—success through yielding. Pure Yin, the Earth receiving all. The mare's perseverance brings benefit. While the creative acts, the receptive completes. Success comes through supporting others, carrying all things with broad virtue. Be gentle, yielding, and supportive.", 'topics_vn': {'fortune': 'Cát. Lợi về lâu dài, cần kiên nhẫn tích lũy.', 'wish': 'Đạt được nếu biết nhờ cậy người khác, không nên tự ý đi đầu.', 'love': 'Bền vững, người nữ hiền thục đảm đang.', 'family': 'Hòa thuận, ấm áp.', 'sickness': 'Bụng, dạ dày, tiêu hóa. Bệnh âm ỉ kéo dài.', 'lost_item': 'Tìm ở nơi thấp, tối, hướng Tây Nam. Đồ vải vóc/gồm sứ.', 'career': 'Làm phó, hỗ trợ, hậu cần rất tốt.'}}, 'Thủy Lôi Truân': {'id': 3, 'vn_name': 'Thủy Lôi Truân', 'zh_name': '屯', 'symbol': '䷂', 'binary': '100010', 'upper': 'Khảm', 'lower': 'Chấn', 'upper_el': 'Thủy', 'lower_el': 'Mộc', 'quai_tu_zh': '元亨，利贞；勿用有攸往，利建侯。', 'quai_tu_vn': 'Nguyên Hanh Lợi Trinh, chớ vội dùng — Khó khăn ban đầu', 'thoan_truyen_zh': '屯，刚柔始交而难生。动乎险中，大亨贞。雷雨之动满盈，天造草昧，宜建侯而不宁。', 'dai_tuong_zh': '云雷，屯。君子以经纶。', 'dai_tuong_vn': 'Mây sấm giao nhau, quân tử kinh luân sắp đặt', 'y_nghia_vn': 'Khó khăn khởi đầu, cần kiên nhẫn vượt qua gian nan', 'loi_khuyen_vn': 'Kiên nhẫn chờ đợi, chuẩn bị kỹ, đừng vội vàng', 'cat_hung': 'BÌNH', 'tap_quai_zh': '見而不失其居', 'tu_quai_zh': '盈天地之間者唯萬物，物之始生', 'gaodao_zh': "屯卦象征艰难初创，震雷动于坎险。'屯元亨利贞，勿用有攸往利建侯'。万事开头难，云雷屯皆窒塞难通。问事事业初创，困难重重但前景光明。", 'gaodao_en': 'Difficulty at the Beginning—supreme success through perseverance. Thunder in the rain—chaotic, challenging beginnings. This hexagram represents the birth pangs of any new enterprise. Difficulty and confusion are natural at the start. Do not rush forward; establish order and gather allies.', 'topics_vn': {'fortune': 'Hung trước Cát sau. Cần kiên nhẫn chờ thời.', 'wish': 'Khó khăn, trắc trở, chưa thành ngay được.', 'love': 'Nhiều sóng gió, hiểu lầm, gia đình ngăn cản.', 'family': 'Bất hòa, lo lắng.', 'sickness': 'Bệnh về thận, bàng quang, chân.', 'lost_item': 'Bị che lấp, khó tìm. Hướng Bắc hoặc Đông.', 'career': 'Khởi nghiệp gian nan, cần người dẫn dắt.'}}, 'Sơn Thủy Mông': {'id': 4, 'vn_name': 'Sơn Thủy Mông', 'zh_name': '蒙', 'symbol': '䷃', 'binary': '010001', 'upper': 'Cấn', 'lower': 'Khảm', 'upper_el': 'Thổ', 'lower_el': 'Thủy', 'quai_tu_zh': '亨。匪我求童蒙，童蒙求我。初筮告，再三渎，渎则不告。利贞。', 'quai_tu_vn': 'Hanh, phi ngã cầu đồng mông — Mông muội cầu ta, không phải ta cầu', 'thoan_truyen_zh': '蒙，山下有险，险而止，蒙。“蒙亨”，以亨行，时中也。“匪我求童蒙，童蒙求我”，志应也。“初筮告”，以刚中也。“再三渎，渎则不告”，渎蒙也。蒙以养正，圣功也。', 'dai_tuong_zh': '山下出泉，蒙。君子以果行育德。', 'dai_tuong_vn': 'Dưới núi có suối, quân tử nuôi đức hạnh', 'y_nghia_vn': 'Mông muội, cần học hỏi, giáo dục, khai sáng', 'loi_khuyen_vn': 'Khiêm tốn học hỏi, tìm thầy, kiên nhẫn giáo dục', 'cat_hung': 'BÌNH', 'tap_quai_zh': '雜而著', 'tu_quai_zh': '物生必蒙，物之稚也', 'gaodao_zh': "蒙卦象征蒙昧启蒙，坎水浸艮山。'蒙亨，匪我求童蒙童蒙求我'。蒙以养正圣功也。问事需学习求教，启蒙之时。", 'gaodao_en': 'Youful Folly—success through education. Water at the foot of the mountain forms a spring. This hexagram indicates a time of inexperience that requires teaching. The teacher does not seek the student; the student seeks the teacher. Proper early education establishes the foundation for future wisdom.', 'topics_vn': {'fortune': 'Trung bình. Đừng làm gì khi chưa hiểu rõ.', 'wish': 'Mơ hồ, không thực tế.', 'love': 'Tình cảm chưa chín chắn, dễ bị lừa dối.', 'family': 'Thiếu sự thấu hiểu.', 'sickness': 'Bệnh do ăn uống, trúng độc, tai mũi họng.', 'lost_item': 'Bị giấu kỹ, tìm ở gần núi hoặc nơi ẩm ướt.', 'career': 'Cần học hỏi thêm, chưa đủ sức đảm đương.'}}, 'Thủy Thiên Nhu': {'id': 5, 'vn_name': 'Thủy Thiên Nhu', 'zh_name': '需', 'symbol': '䷄', 'binary': '111010', 'upper': 'Khảm', 'lower': 'Càn', 'upper_el': 'Thủy', 'lower_el': 'Kim', 'quai_tu_zh': '有孚，光亨，贞吉，利涉大川。', 'quai_tu_vn': 'Hữu phu, quang hanh trinh cát — Có lòng thành, sáng sủa hanh thông', 'thoan_truyen_zh': '“需”，须也；险在前也。刚健而不陷，其义不困穷矣。“需，有孚，光亨，贞吉”，位乎天位，以正中也。“利涉大川”，往有功也。', 'dai_tuong_zh': '云上于天，需。君子以饮食宴乐。', 'dai_tuong_vn': 'Mây lên trời, quân tử ẩm thực yến lạc', 'y_nghia_vn': 'Chờ đợi, nuôi dưỡng, kiên nhẫn chờ thời cơ', 'loi_khuyen_vn': 'Chờ đợi đúng lúc, không nóng vội, chuẩn bị sẵn sàng', 'cat_hung': 'CÁT', 'tap_quai_zh': '不進也', 'tu_quai_zh': '物稚不可不養，飲食之道', 'gaodao_zh': "需卦象征等待需求，乾刚遇坎险。'需有孚光亨贞吉，利涉大川'。需于郊不犯难，需于沙容民畜众。问事需耐心等待，不可急躁。", 'gaodao_en': 'Waiting—success through trust and patience. Clouds rise to Heaven, waiting to rain. This hexagram indicates a time when waiting is necessary and beneficial. Wait with confidence and sincerity; the needed resources will arrive. Cross great waters when the proper time comes.', 'topics_vn': {'fortune': 'Cần kiên nhẫn. Nóng vội sẽ hỏng việc.', 'wish': 'Chưa đến lúc, chờ đợi sẽ có kết quả.', 'love': 'Cần thời gian tìm hiểu, đừng ép buộc.', 'family': 'Bình yên nhưng có sự trì trệ.', 'sickness': 'Bệnh tiêu hóa, phù nề, ăn uống quá độ.', 'lost_item': 'Sẽ tìm thấy sau một thời gian.', 'career': 'Chờ cơ hội, đừng chuyển việc lúc này.'}}, 'Thiên Thủy Tụng': {'id': 6, 'vn_name': 'Thiên Thủy Tụng', 'zh_name': '讼', 'symbol': '䷅', 'binary': '010111', 'upper': 'Càn', 'lower': 'Khảm', 'upper_el': 'Kim', 'lower_el': 'Thủy', 'quai_tu_zh': '有孚，窒惕，中吉；终凶。利见大人，不利涉大川。', 'quai_tu_vn': 'Hữu phu truất dịch — Có lòng thành nhưng bị ngăn trở', 'thoan_truyen_zh': '讼，上刚下险，险而健，讼。“讼：有孚，窒惕，中吉”，刚来而得中也。“终凶”，讼不可成也。“利见大人”，尚中正也。“不利涉大川”，入于渊也。', 'dai_tuong_zh': '天与水违行，讼。君子以作事谋始。', 'dai_tuong_vn': 'Trời nước trái chiều, quân tử mưu sự từ đầu', 'y_nghia_vn': 'Tranh chấp, kiện tụng, bất hòa, cần hòa giải', 'loi_khuyen_vn': 'Tránh tranh chấp, tìm người phân xử, đừng cố chấp', 'cat_hung': 'HUNG', 'tap_quai_zh': '不親也', 'tu_quai_zh': '飲食必有訟', 'gaodao_zh': "讼卦象征争讼诉讼，坎险遇乾刚。'讼有孚窒惕，中吉终凶'，健而险也。天与水违行，酿成讼端。问事宜和解，诉讼则凶。君子做事谋始，防患于未然。", 'gaodao_en': 'Conflict—there is sincerity but it is blocked. Caution brings good fortune in the middle, misfortune at the end. Heaven and water move in opposite directions, creating friction. This hexagram advises settling disputes through mediation rather than litigation. The superior person plans ahead to prevent conflict.', 'topics_vn': {'fortune': 'Hung. Đề phòng khẩu thiệt thị phi.', 'wish': 'Bị cản trở, tranh cãi.', 'love': 'Cãi vã, bất đồng, dễ chia tay.', 'family': 'Bất hòa, tranh chấp tài sản.', 'sickness': 'Đầu óc căng thẳng, bệnh máu huyết.', 'lost_item': 'Bị người khác lấy hoặc tranh chấp.', 'career': 'Kiện tụng, đồng nghiệp chơi xấu.'}}, 'Địa Thủy Sư': {'id': 7, 'vn_name': 'Địa Thủy Sư', 'zh_name': '师', 'symbol': '䷆', 'binary': '010000', 'upper': 'Khôn', 'lower': 'Khảm', 'upper_el': 'Thổ', 'lower_el': 'Thủy', 'quai_tu_zh': '贞，丈人吉，无咎。', 'quai_tu_vn': 'Trinh, trượng nhân cát — Chính đáng, người lớn tuổi cát', 'thoan_truyen_zh': '师，众也；贞，正也。能以众正，可以王矣。刚中而应，行险而顺，以此毒天下，而民从之，“吉”又何“咎”矣！', 'dai_tuong_zh': '地中有水，师。君子以容民畜众。', 'dai_tuong_vn': 'Đất chứa nước, quân tử dung dân nuôi chúng', 'y_nghia_vn': 'Quân đội, tổ chức, kỷ luật, cần người lãnh đạo', 'loi_khuyen_vn': 'Cần kỷ luật, tổ chức tốt, tìm người có kinh nghiệm', 'cat_hung': 'BÌNH', 'tap_quai_zh': '憂', 'tu_quai_zh': '訟必有眾起，師者眾也', 'gaodao_zh': "地水师卦象征兵众竞争，坎水浸坤地。'师贞丈人吉无咎'，师或舆尸贞凶。行险而顺养兵以正。问事竞争激烈，需要策略。", 'gaodao_en': 'The Army—success through proper command. Water in the Earth—dangerous but organized force. This hexagram indicates the need for disciplined organization and proper leadership. Success requires an experienced commander and correct principles. Without proper command, danger and disorder result.', 'topics_vn': {'fortune': 'Có hung hiểm nhưng nếu kỷ luật sẽ thắng.', 'wish': 'Khó khăn, phải đấu tranh mới có.', 'love': 'Phức tạp, có người thứ ba hoặc tình tay ba.', 'family': 'Có tranh chấp nhưng giải quyết được bằng uy quyền.', 'sickness': 'Dịch bệnh lây lan, sốt.', 'lost_item': 'Mất nơi đông người.', 'career': 'Cạnh tranh khốc liệt, quân đội công an tốt.'}}, 'Thủy Địa Tỷ': {'id': 8, 'vn_name': 'Thủy Địa Tỷ', 'zh_name': '比', 'symbol': '䷇', 'binary': '000010', 'upper': 'Khảm', 'lower': 'Khôn', 'upper_el': 'Thủy', 'lower_el': 'Thổ', 'quai_tu_zh': '吉。原筮，元永贞，无咎。不宁方来，后夫凶。', 'quai_tu_vn': 'Cát, nguyên phệ nguyên vĩnh trinh — Tốt lành, gần gũi thân mật', 'thoan_truyen_zh': '比，吉也；比，辅也，下顺从也。“原筮，元永贞，无咎”，以刚中也。“不宁方来”，上下应也；“后夫凶”，其道穷也。', 'dai_tuong_zh': '地上有水，比。先王以建万国，亲诸侯。', 'dai_tuong_vn': 'Nước trên đất, quân tử thân cận chư hầu', 'y_nghia_vn': 'Thân cận, hợp tác, liên minh, đoàn kết', 'loi_khuyen_vn': 'Đoàn kết, tìm đồng minh, hợp tác chân thành', 'cat_hung': 'CÁT', 'tap_quai_zh': '樂', 'tu_quai_zh': '眾必有所比', 'gaodao_zh': "比卦象征亲近团结，坤地从坎水。'比吉，原筮元永贞，不宁方来'。比以辅为主，先迷后得主。问事宜与人亲近，团结合作。", 'gaodao_en': 'Holding Together—success through alliance. Water on Earth flows together, uniting all. This hexagram indicates benefits that come through proper association and loyalty. The insecure seek connection. Success comes through finding the right leader or group and holding together with them.', 'topics_vn': {'fortune': 'Cát. Có quý nhân phù trợ, bạn bè giúp đỡ.', 'wish': 'Thành công nhờ sự hợp tác.', 'love': 'Tình cảm thắm thiết, xứng đôi vừa lứa.', 'family': 'Hòa thuận, vui vẻ.', 'sickness': 'Mau khỏi nhờ thầy giỏi thuốc hay.', 'lost_item': 'Tìm thấy nhờ người khác chỉ giúp.', 'career': 'Hợp tác làm ăn tốt, ngoại giao thuận lợi.'}}, 'Phong Thiên Tiểu Súc': {'id': 9, 'vn_name': 'Phong Thiên Tiểu Súc', 'zh_name': '小畜', 'symbol': '䷈', 'binary': '111011', 'upper': 'Tốn', 'lower': 'Càn', 'upper_el': 'Mộc', 'lower_el': 'Kim', 'quai_tu_zh': '亨。密云不雨，自我西郊。', 'quai_tu_vn': 'Hanh, mật vân bất vũ — Mây dày chưa mưa, tích lũy nhỏ', 'thoan_truyen_zh': '“小畜”，柔得位而上下应之，曰小畜。健而巽，刚中而志行，乃“亨”。“密云不雨”，尚往也；“自我西郊”，施未行也。', 'dai_tuong_zh': '风行天上，小畜。君子以懿文德。', 'dai_tuong_vn': 'Gió trên trời, quân tử văn đức', 'y_nghia_vn': 'Tích lũy nhỏ, chưa đủ lực, cần kiên nhẫn thêm', 'loi_khuyen_vn': 'Tích lũy từ từ, đừng cố làm lớn khi chưa đủ sức', 'cat_hung': 'CÁT', 'tap_quai_zh': '寡也', 'tu_quai_zh': '比必有所畜', 'gaodao_zh': "小畜卦象征小有蓄积，巽风畜乾刚。'小畜亨，密云不雨自我西郊'。问事小有收获，宜继续积累。君子以懿文德。", 'gaodao_en': 'The Taming Power of the Small—success through accumulation. Wind across Heaven gathers clouds but does not yet rain. This hexagram indicates a time of small gains and gradual accumulation. The superior person cultivates literary virtue while waiting for the proper time to act.', 'topics_vn': {'fortune': 'Trung bình. Chỉ nên làm việc nhỏ.', 'wish': 'Chưa thành, bị kìm hãm.', 'love': 'Có chút trục trặc nhỏ, giận hờn vu vơ.', 'family': 'Có bất đồng ý kiến nhưng không lớn.', 'sickness': 'Bệnh hô hấp nhẹ, ngực bụng đầy trướng.', 'lost_item': 'Tìm thấy ở gần, phía Đông Nam.', 'career': 'Chưa thăng tiến ngay, cần tích lũy thêm.'}}, 'Thiên Trạch Lý': {'id': 10, 'vn_name': 'Thiên Trạch Lý', 'zh_name': '履', 'symbol': '䷉', 'binary': '110111', 'upper': 'Càn', 'lower': 'Đoài', 'upper_el': 'Kim', 'lower_el': 'Kim', 'quai_tu_zh': '履虎尾，不咥人，亨。', 'quai_tu_vn': 'Lý hổ vĩ, bất điệt nhân — Giẫm đuôi hổ mà không bị cắn', 'thoan_truyen_zh': '履，柔履刚也。说而应乎乾，是以“履虎尾，不咥人，亨”。刚中正，履帝位而不疚，光明也。', 'dai_tuong_zh': '上天下泽，履。君子以辨上下，定民志。', 'dai_tuong_vn': 'Trời trên đầm, quân tử phân biệt trên dưới', 'y_nghia_vn': 'Lễ nghi, cẩn trọng, đi đúng đường, phân biệt', 'loi_khuyen_vn': 'Cẩn thận từng bước, giữ lễ, biết trên biết dưới', 'cat_hung': 'CÁT', 'tap_quai_zh': '不處也', 'tu_quai_zh': '物畜然後有禮，履者禮也', 'gaodao_zh': "履卦象为履行礼仪，兑泽遇乾刚。卦辞'履虎尾不咥人亨'，踩虎尾而不被咬，行事谨慎则吉祥。辨上下定民志，礼之用和为贵。君子体履，行己敬而与人诚。问事宜脚踏实地，谨慎行事，不可冒进。", 'gaodao_en': "Treading upon the tiger's tail without being bitten—success through proper conduct. This hexagram emphasizes careful, respectful behavior in all relationships. The superior person distinguishes high and low, establishing proper order. Progress comes through courtesy and caution, not recklessness.", 'topics_vn': {'fortune': 'Có rủi ro. Cần cư xử đúng mực, lễ phép.', 'wish': 'Thành công nếu biết khiêm tốn và tuân thủ quy tắc.', 'love': 'Chênh lệch địa vị, cần khéo léo cư xử.', 'family': 'Nề nếp gia phong.', 'sickness': 'Bệnh phổi, miệng lưỡi, xương khớp.', 'lost_item': 'Khó tìm, hoặc vật nguy hiểm.', 'career': 'Làm việc với người khó tính, cần cẩn trọng.'}}, 'Địa Thiên Thái': {'id': 11, 'vn_name': 'Địa Thiên Thái', 'zh_name': '泰', 'symbol': '䷊', 'binary': '111000', 'upper': 'Khôn', 'lower': 'Càn', 'upper_el': 'Thổ', 'lower_el': 'Kim', 'quai_tu_zh': '小往大来，吉，亨。', 'quai_tu_vn': 'Tiểu vãng đại lai, cát hanh — Nhỏ đi lớn đến, cát hanh thông', 'thoan_truyen_zh': '“泰，小往大来，吉，亨”，则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人：君子道长，小人道消也。', 'dai_tuong_zh': '天地交，泰。后以财成天地之道，辅相天地之宜，以左右民。', 'dai_tuong_vn': 'Trời đất giao hòa, quân tử tài thành thiên địa đạo', 'y_nghia_vn': 'Thái bình, hanh thông, âm dương hòa hợp, vạn sự tốt', 'loi_khuyen_vn': 'Tận dụng thời kỳ thuận lợi, mở rộng, hợp tác', 'cat_hung': 'ĐẠI CÁT', 'tap_quai_zh': '反其類也', 'tu_quai_zh': '履而泰然後安，泰者通也', 'gaodao_zh': "泰卦象征通泰和谐，乾天交坤地。'小往大来吉亨'，天地交泰。泰之时义大矣哉，吉在交济。问事运势亨通，万事如意。", 'gaodao_en': 'Peace—success through interchange. Heaven and Earth unite, creating harmony and flourishing. This hexagram indicates a time of great harmony when the small departs and the great arrives. The interaction of Heaven and Earth brings peace and prosperity to all things.', 'topics_vn': {'fortune': 'Đại cát. Mọi việc thuận lợi.', 'wish': 'Cầu được ước thấy.', 'love': 'Hạnh phúc, hòa hợp tuyệt đối.', 'family': 'Giàu sang, an khang thịnh vượng.', 'sickness': 'Mau lành, sức khỏe dồi dào.', 'lost_item': 'Sẽ tìm thấy, đồ vật còn nguyên vẹn.', 'career': 'Thăng quan tiến chức, kinh doanh phát đạt.'}}, 'Thiên Địa Bĩ': {'id': 12, 'vn_name': 'Thiên Địa Bĩ', 'zh_name': '否', 'symbol': '䷋', 'binary': '000111', 'upper': 'Càn', 'lower': 'Khôn', 'upper_el': 'Kim', 'lower_el': 'Thổ', 'quai_tu_zh': '否之匪人，不利君子贞，大往小来。', 'quai_tu_vn': 'Bĩ chi phỉ nhân — Bế tắc, trời đất không giao', 'thoan_truyen_zh': '“否之匪人，不利君子贞，大往小来”，则是天地不交而万物不通也，上下不交而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子，小人道长，君子道消也。', 'dai_tuong_zh': '天地不交，否。君子以俭德辟难，不可荣以禄。', 'dai_tuong_vn': 'Trời đất không giao, quân tử kiệm đức tránh nạn', 'y_nghia_vn': 'Bế tắc, trì trệ, âm dương cách biệt, vạn sự khó', 'loi_khuyen_vn': 'Kiên nhẫn chờ đợi, tiết kiệm, tránh mạo hiểm', 'cat_hung': 'HUNG', 'tap_quai_zh': '反其類也', 'tu_quai_zh': '物不可以終通', 'gaodao_zh': "否卦象征闭塞不通，坤阴下凝。'否之匪人不利君子贞，大往小来'。天气上升，地气下沉，阴阳不交。问事阻隔不顺，宜守正待时。小人道长，君子道消，闭塞之象。", 'gaodao_en': "Stagnation—Heaven and Earth do not unite. The creative energy rises, the receptive sinks, creating separation. This hexagram indicates a period when the way of the inferior person prevails and the superior person's way withdraws. Stand firm and wait—the stagnation will eventually transform.", 'topics_vn': {'fortune': 'Hung. Mọi việc đình trệ.', 'wish': 'Không thành. Bị cản trở.', 'love': 'Chia ly, không hợp nhau.', 'family': 'Lạnh nhạt, ly tán.', 'sickness': 'Bệnh nặng, tắc nghẽn khí huyết.', 'lost_item': 'Mất hẳn, không tìm được.', 'career': 'Bị chèn ép, giáng chức, thất nghiệp.'}}, 'Thiên Hỏa Đồng Nhân': {'id': 13, 'vn_name': 'Thiên Hỏa Đồng Nhân', 'zh_name': '同人', 'symbol': '䷌', 'binary': '101111', 'upper': 'Càn', 'lower': 'Ly', 'upper_el': 'Kim', 'lower_el': 'Hỏa', 'quai_tu_zh': '同人于野，亨。利涉大川，利君子贞。', 'quai_tu_vn': 'Đồng Nhân vu dã, hanh — Cùng người ngoài đồng, hanh thông', 'thoan_truyen_zh': '同人，柔得位得中而应乎乾，曰同人。同人曰：“同人于野，亨。利涉大川”，乾行也。文明以健，中正而应。“君子”，正也。唯君子为能通天下之志。', 'dai_tuong_zh': '天与火，同人。君子以类族辨物。', 'dai_tuong_vn': 'Trời với lửa, quân tử loại tộc biện vật', 'y_nghia_vn': 'Đồng tâm hiệp lực, hợp tác, cộng đồng, hòa hợp', 'loi_khuyen_vn': 'Đoàn kết, hợp tác rộng rãi, công bằng với mọi người', 'cat_hung': 'CÁT', 'tap_quai_zh': '親也', 'tu_quai_zh': '物不可以終否', 'gaodao_zh': "同人卦象征会同同心，离火上照。'同人于野亨，利涉大川'。会同之道贵在正大，以文德感化天下。伏戎于莽、乘其墉者弗克攻而吉，争讼则凶。问事利与人合作，共谋发展。", 'gaodao_en': 'Fellowship with others in the open—success, beneficial to cross great waters. This hexagram represents union and cooperation among people. Success comes through openness, shared purpose, and cultural influence. Competition and conflict lead to misfortune; cooperation brings benefit.', 'topics_vn': {'fortune': 'Cát. Hợp tác thành công.', 'wish': 'Thành tựu nhờ sức mạnh tập thể.', 'love': 'Tình yêu trong sáng, được mọi người ủng hộ.', 'family': 'Đoàn tụ, vui vẻ.', 'sickness': 'Sốt cao, viêm nhiễm nhưng mau khỏi.', 'lost_item': 'Tìm thấy ở nơi công cộng, sáng sủa.', 'career': 'Hội nhóm, công ty cổ phần phát triển.'}}, 'Hỏa Thiên Đại Hữu': {'id': 14, 'vn_name': 'Hỏa Thiên Đại Hữu', 'zh_name': '大有', 'symbol': '䷍', 'binary': '111101', 'upper': 'Ly', 'lower': 'Càn', 'upper_el': 'Hỏa', 'lower_el': 'Kim', 'quai_tu_zh': '元亨。', 'quai_tu_vn': 'Nguyên hanh — Có lớn, rất hanh thông', 'thoan_truyen_zh': '大有，柔得尊位大中，而上下应之，曰大有。其德刚健而文明，应乎天而时行，是以“元亨”。', 'dai_tuong_zh': '火在天上，大有。君子以遏恶扬善，顺天休命。', 'dai_tuong_vn': 'Lửa trên trời, quân tử ngăn ác dương thiện thuận mệnh trời', 'y_nghia_vn': 'Giàu có, thịnh vượng, sở hữu lớn, vinh quang', 'loi_khuyen_vn': 'Khiêm tốn trong giàu có, dùng tài sản làm việc thiện', 'cat_hung': 'ĐẠI CÁT', 'tap_quai_zh': '眾也', 'tu_quai_zh': '與人同者物必歸焉', 'gaodao_zh': "大有卦象征丰盛富有，乾刚照离光。'大有元亨'，柔得尊位大中上下应之，富有之谓大业，日新之谓盛德。问事运势亨通，收获丰硕。", 'gaodao_en': 'Possession in Great Measure—supreme success. Fire in Heaven shines far and wide. This hexagram indicates abundant resources and the wise management of great possessions. Success comes through holding a central position while remaining open and responsive to those above and below.', 'topics_vn': {'fortune': 'Đại cát. Tài lộc dồi dào.', 'wish': 'Thành công rực rỡ.', 'love': 'Hào nhoáng, đối phương điều kiện tốt.', 'family': 'Phú quý, danh giá.', 'sickness': 'Sốt cao, bệnh tim mạch, mắt.', 'lost_item': 'Tìm thấy ở nơi cao, sáng, hướng Nam.', 'career': 'Thành đạt, danh tiếng vang xa.'}}, 'Địa Sơn Khiêm': {'id': 15, 'vn_name': 'Địa Sơn Khiêm', 'zh_name': '谦', 'symbol': '䷎', 'binary': '001000', 'upper': 'Khôn', 'lower': 'Cấn', 'upper_el': 'Thổ', 'lower_el': 'Thổ', 'quai_tu_zh': '亨，君子有终。', 'quai_tu_vn': 'Hanh, quân tử hữu chung — Khiêm tốn hanh thông trọn vẹn', 'thoan_truyen_zh': '“谦，亨”，天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾，君子之终也。', 'dai_tuong_zh': '地中有山，谦。君子以裒多益寡，称物平施。', 'dai_tuong_vn': 'Núi trong đất, quân tử bớt nhiều thêm ít, cân bằng', 'y_nghia_vn': 'Khiêm tốn, nhún nhường, đức hạnh cao quý', 'loi_khuyen_vn': 'Giữ khiêm tốn trong mọi hoàn cảnh, được lòng người', 'cat_hung': 'CÁT', 'tap_quai_zh': '輕也', 'tu_quai_zh': '有大者不可以盈', 'gaodao_zh': "谦卦象征谦虚谦让，艮山在于坤地。'谦亨君子有终'，谦谦君子卑以自牧。劳谦君子万民服也。问事谦虚谨慎会带来好运。", 'gaodao_en': 'Modesty—success through humility. The mountain within the Earth lowers itself. This hexagram indicates that modesty brings success in all undertakings. The superior person lowers themselves to cultivate virtue. Modest, hardworking leadership brings universal respect and good fortune.', 'topics_vn': {'fortune': 'Cát. Càng khiêm tốn càng được lợi.', 'wish': 'Thành công chậm nhưng chắc.', 'love': 'Tình cảm chân thành, bền vững.', 'family': 'Kính trên nhường dưới.', 'sickness': 'Bệnh tỳ vị, tiêu hóa mãn tính.', 'lost_item': 'Nằm dưới thấp, bị che lấp.', 'career': 'Thăng tiến nhờ đức độ.'}}, 'Lôi Địa Dự': {'id': 16, 'vn_name': 'Lôi Địa Dự', 'zh_name': '豫', 'symbol': '䷏', 'binary': '000100', 'upper': 'Chấn', 'lower': 'Khôn', 'upper_el': 'Mộc', 'lower_el': 'Thổ', 'quai_tu_zh': '利建侯，行师。', 'quai_tu_vn': 'Lợi kiến hầu hành sư — Sấm vang đất, vui vẻ, khởi sự', 'thoan_truyen_zh': '豫，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况“建侯，行师”乎？天地以顺动，故日月不过，而四时不忒；圣人以顺动，则刑罚清而民服。豫之时义大矣哉！', 'dai_tuong_zh': '雷出地奋，豫；先王以作乐崇德，殷荐之上帝，以配祖考。', 'dai_tuong_vn': 'Sấm ra từ đất, tiên vương tác nhạc sùng đức', 'y_nghia_vn': 'Vui vẻ, hân hoan, thuận lợi khởi sự, lạc quan', 'loi_khuyen_vn': 'Hành động khi hứng khởi, nhưng đừng quá phóng túng', 'cat_hung': 'CÁT', 'tap_quai_zh': '怠也', 'tu_quai_zh': '有大而能謙必豫', 'gaodao_zh': "豫卦象征愉悦安乐，坤地从震雷。'豫利建侯行师'，雷出地奋，先王以作乐。问事心情愉悦，宜做好准备。", 'gaodao_en': 'Enthusiasm—benefit through preparation and leadership. Thunder emerges from the Earth, energizing all things. This hexagram indicates a time of joy and enthusiasm that supports productive action. The ancient kings used music to honor virtue. Proper preparation and timing lead to success.', 'topics_vn': {'fortune': 'Cát. Niềm vui đến bất ngờ.', 'wish': 'Thuận lợi.', 'love': 'Vui vẻ, lãng mạn.', 'family': 'Có hỷ sự, tiệc tùng.', 'sickness': 'Bệnh gan, chấn động thần kinh.', 'lost_item': 'Tìm thấy ở hướng Đông.', 'career': 'Mở rộng kinh doanh, khởi công tốt.'}}, 'Trạch Lôi Tùy': {'id': 17, 'vn_name': 'Trạch Lôi Tùy', 'zh_name': '随', 'symbol': '䷐', 'binary': '100110', 'upper': 'Đoài', 'lower': 'Chấn', 'upper_el': 'Kim', 'lower_el': 'Mộc', 'quai_tu_zh': '元亨，利贞，无咎。', 'quai_tu_vn': 'Nguyên hanh lợi trinh — Đi theo, thuận theo tự nhiên', 'thoan_truyen_zh': '随，刚来而下柔，动而说，随。大亨，贞，“无咎”，而天下随时。随之时义大矣哉！', 'dai_tuong_zh': '泽中有雷，随。君子以向晦入宴息。', 'dai_tuong_vn': 'Đầm có sấm, quân tử hướng tối nhập nghỉ', 'y_nghia_vn': 'Thuận theo, thích ứng, đi theo xu hướng', 'loi_khuyen_vn': 'Thuận theo hoàn cảnh, linh hoạt thích ứng', 'cat_hung': 'CÁT', 'tap_quai_zh': '無故也', 'tu_quai_zh': '豫必有隨', 'gaodao_zh': "随卦象征随顺时势，震雷从兑悦。'随元亨利贞无咎'，泽中有雷，君子以向晦入宴息。随之道在随时，官有渝从正吉，出门交有功。问事宜顺应时势，不可固执。", 'gaodao_en': 'Following—supreme success through adaptation. Thunder in the lake indicates following natural rhythms. The wise person follows the time, resting when it is dark and acting when it is light. Success comes through flexibility and harmonious adaptation to circumstances, not rigid adherence to plans.', 'topics_vn': {'fortune': 'Bình hòa. Nên theo người khác thì tốt.', 'wish': 'Được như ý nếu không cố chấp.', 'love': 'Người nữ theo người nam, thuận tình.', 'family': 'Hòa thuận.', 'sickness': 'Bệnh lây truyền, di chuyển.', 'lost_item': 'Đã bị mang đi xa, hoặc rơi khi đi đường.', 'career': 'Làm nhân viên tốt, đổi việc theo hướng mới.'}}, 'Sơn Phong Cổ': {'id': 18, 'vn_name': 'Sơn Phong Cổ', 'zh_name': '蛊', 'symbol': '䷑', 'binary': '011001', 'upper': 'Cấn', 'lower': 'Tốn', 'upper_el': 'Thổ', 'lower_el': 'Mộc', 'quai_tu_zh': '元亨，利涉大川。先甲三日，后甲三日。', 'quai_tu_vn': 'Nguyên hanh, lợi thiệp đại xuyên — Sửa chữa sai lầm của cha', 'thoan_truyen_zh': '蛊，刚上而柔下，巽而止，蛊。蛊，“元亨”，而天下治也。“利涉大川”，往有事也。“先甲三日，后甲三日”，终则有始，天行也。', 'dai_tuong_zh': '山下有风，蛊。君子以振民育德。', 'dai_tuong_vn': 'Dưới núi có gió, quân tử chấn dân dục đức', 'y_nghia_vn': 'Mục nát, cần sửa chữa, cải cách, khắc phục lỗi cũ', 'loi_khuyen_vn': 'Sửa chữa sai lầm cũ, cải cách mạnh mẽ, đừng để mục nát', 'cat_hung': 'BÌNH', 'tap_quai_zh': '則飭也', 'tu_quai_zh': '以喜隨人者必有事，蠱者事也', 'gaodao_zh': "蛊卦象征积弊改革，巽风入艮山。'蛊元亨利涉大川，先甲三日后甲三日'。蛊因人兴必有所以蛊。问事需革除积弊，改革创新。", 'gaodao_en': 'Work on What Has Been Spoiled—supreme success. Wind in the mountains disperses decay. This hexagram indicates a time when accumulated problems must be addressed. Reform and renovation are necessary. Calculate the proper timing (three days before and after) for instituting change.', 'topics_vn': {'fortune': 'Hung. Mọi việc đang xuống cấp.', 'wish': 'Không thành, cần sửa sai.', 'love': 'Mối quan hệ độc hại, có sự lừa dối.', 'family': 'Gia đạo suy đồi, con cái hư hỏng.', 'sickness': 'Trúng độc, bệnh di truyền, ký sinh trùng.', 'lost_item': 'Đã hỏng hoặc bị sâu mọt.', 'career': 'Công việc trì trệ, cần cải tổ.'}}, 'Địa Trạch Lâm': {'id': 19, 'vn_name': 'Địa Trạch Lâm', 'zh_name': '临', 'symbol': '䷒', 'binary': '110000', 'upper': 'Khôn', 'lower': 'Đoài', 'upper_el': 'Thổ', 'lower_el': 'Kim', 'quai_tu_zh': '元亨，利贞；至于八月，有凶。', 'quai_tu_vn': 'Nguyên hanh lợi trinh, chí vu bát nguyệt hữu hung — Đến gần, tiếp cận', 'thoan_truyen_zh': '临，刚浸而长，说而顺，刚中而应。大“亨”以正，天之道也。“至于八月，有凶”，消不久也。', 'dai_tuong_zh': '泽上有地，临。君子以教思无穷，容保民无疆。', 'dai_tuong_vn': 'Đất trên đầm, quân tử giáo dục vô cùng', 'y_nghia_vn': 'Tiếp cận, giám sát, lãnh đạo tiếp cận dân chúng', 'loi_khuyen_vn': 'Chủ động tiếp cận, nhưng biết rằng thịnh sẽ suy', 'cat_hung': 'CÁT', 'tap_quai_zh': '與也', 'tu_quai_zh': '有事而後可大，臨者大也', 'gaodao_zh': "地泽临卦象征监临督导，兑泽临坤地。'临元亨利贞，至于八月有凶'。以大临小以刚临柔。问事机会来临，宜积极把握。", 'gaodao_en': 'Approach—supreme success through proper leadership. The lake approaches the Earth, bringing nourishment. This hexagram indicates a time when great persons approach to teach and assist. However, note the warning: by August (the eighth month), vigilance is required as cycles change.', 'topics_vn': {'fortune': 'Cát. Đang đà phát triển.', 'wish': 'Tiến triển tốt.', 'love': 'Tình cảm mặn nồng, quan tâm chăm sóc.', 'family': 'Sum vầy, bảo bọc.', 'sickness': 'Bệnh phụ khoa, tiêu hóa.', 'lost_item': 'Tìm thấy ở gần nước.', 'career': 'Quản lý, giám sát tốt.'}}, 'Phong Địa Quan': {'id': 20, 'vn_name': 'Phong Địa Quan', 'zh_name': '观', 'symbol': '䷓', 'binary': '000011', 'upper': 'Tốn', 'lower': 'Khôn', 'upper_el': 'Mộc', 'lower_el': 'Thổ', 'quai_tu_zh': '盥而不荐，有孚颙若。', 'quai_tu_vn': 'Quán nhi bất tiến, hữu phu ngung nhược — Quan sát từ trên cao', 'thoan_truyen_zh': '大观在上，顺而巽，中正以观天下。“观，盥而不荐，有孚颙若”，下观而化也。观天之神道，而四时不忒，圣人以神道设教，而天下服矣。', 'dai_tuong_zh': '风行地上，观。先王以省方观民设教。', 'dai_tuong_vn': 'Gió trên đất, quân tử tuần phương quan dân', 'y_nghia_vn': 'Quan sát, chiêm nghiệm, nhìn nhận toàn cảnh', 'loi_khuyen_vn': 'Quan sát kỹ trước khi hành động, suy ngẫm', 'cat_hung': 'BÌNH', 'tap_quai_zh': '求也', 'tu_quai_zh': '物大然後可觀', 'gaodao_zh': "观卦象征观察审视，坤地从巽风。'观盥而不荐，有孚颙若'。神道设教，圣人以神道设教而天下服。问事需冷静观察形势，不可轻举妄动。", 'gaodao_en': 'Contemplation—success through observation. Wind across the Earth reaches everywhere. This hexagram indicates a time for careful observation and consideration before action. The ritual is contemplated but not yet performed. Through calm, respectful observation, one gains the insight needed for right action.', 'topics_vn': {'fortune': 'Trung bình. Nên xem xét kỹ trước khi làm.', 'wish': 'Chưa vội được.', 'love': 'Đang tìm hiểu, chưa quyết định.', 'family': 'Nghiêm túc, soi xét lẫn nhau.', 'sickness': 'Bệnh phong, khí huyết kém.', 'lost_item': 'Tìm thấy ở nơi thoáng gió.', 'career': 'Nghiên cứu, đánh giá, kiểm tra.'}}, 'Hỏa Lôi Phệ Hạp': {'id': 21, 'vn_name': 'Hỏa Lôi Phệ Hạp', 'zh_name': '噬嗑', 'symbol': '䷔', 'binary': '100101', 'upper': 'Ly', 'lower': 'Chấn', 'upper_el': 'Hỏa', 'lower_el': 'Mộc', 'quai_tu_zh': '亨，利用狱。', 'quai_tu_vn': 'Hanh, lợi dụng ngục — Cắn đứt vật cản, xử phạt', 'thoan_truyen_zh': '颐中有物，曰噬嗑。噬嗑而亨，刚柔分，动而明，雷电合而章。柔得中而上行，虽不当位，“利用狱”也。', 'dai_tuong_zh': '雷电，噬嗑。先王以明罚敕法。', 'dai_tuong_vn': 'Sấm sét cùng lửa, tiên vương minh phạt sắc pháp', 'y_nghia_vn': 'Phán xét, xử phạt, loại bỏ chướng ngại', 'loi_khuyen_vn': 'Giải quyết dứt khoát, công bằng, loại bỏ trở ngại', 'cat_hung': 'CÁT', 'tap_quai_zh': '食也', 'tu_quai_zh': '可觀而後有所合，嗑者合也', 'gaodao_zh': "噬嗑卦象征决断执行，离电遇震雷。'噬嗑亨，利用狱'，颐中有物曰噬嗑。刚柔分动而明，雷电合而章。问事需果断处理事务，除障碍。", 'gaodao_en': 'Biting Through—success through decisive enforcement. Lightning and thunder unite to illuminate and move. This hexagram represents the need to remove obstacles through decisive action, like biting through tough material. Proper legal or disciplinary measures bring success in removing hindrances.', 'topics_vn': {'fortune': 'Có trở ngại nhưng sẽ vượt qua nếu quyết đoán.', 'wish': 'Phải tranh đấu mới được.', 'love': 'Hay cãi vã, ghen tuông.', 'family': 'Có xích mích, kiện tụng.', 'sickness': 'Đau răng, xương khớp, ăn uống kém.', 'lost_item': 'Bị kẹt ở đâu đó, hoặc bị người lấy.', 'career': 'Pháp luật, thi hành án, cải tổ mạnh.'}}, 'Sơn Hỏa Bí': {'id': 22, 'vn_name': 'Sơn Hỏa Bí', 'zh_name': '贲', 'symbol': '䷕', 'binary': '101001', 'upper': 'Cấn', 'lower': 'Ly', 'upper_el': 'Thổ', 'lower_el': 'Hỏa', 'quai_tu_zh': '亨，小利有攸往。', 'quai_tu_vn': 'Hanh, tiểu lợi hữu du vãng — Trang sức, văn vẻ đẹp đẽ', 'thoan_truyen_zh': '贲，亨；柔来而文刚，故亨。分刚上而文柔，故“小利有攸往”，天文也；文明以止，人文也。观乎天文，以察时变；观乎人文，以化成天下。', 'dai_tuong_zh': '山下有火，贲。君子以明庶政，无敢折狱。', 'dai_tuong_vn': 'Dưới núi có lửa, quân tử minh thứ triết ngục', 'y_nghia_vn': 'Trang sức, vẻ đẹp bề ngoài, văn hóa, nghệ thuật', 'loi_khuyen_vn': 'Chú trọng nội dung hơn hình thức, đẹp phải có chất', 'cat_hung': 'CÁT', 'tap_quai_zh': '無色也', 'tu_quai_zh': '物不可以苟合而已，賁者飾也', 'gaodao_zh': "贲卦象征文饰美化，离火照艮山。'贲亨小利有攸往'，文明以止人文也。问事宜注重外表，但不可过分。", 'gaodao_en': 'Grace—success in small matters. Fire at the foot of the mountain illuminates and adorns. This hexagram indicates the appropriate use of ornament and culture to beautify and refine. Grace brings benefit, but should not become the substance. Success in small affairs; be cautious in great ones.', 'topics_vn': {'fortune': 'Tiểu cát. Tốt mã rã đám.', 'wish': 'Được tiếng mà không được miếng.', 'love': 'Lãng mạn nhưng thiếu thực tế.', 'family': 'Bề ngoài vui vẻ, bên trong lo âu.', 'sickness': 'Bệnh ngoài da, tim mạch nhẹ.', 'lost_item': 'Tìm thấy ở nơi có ánh sáng, trang trí đẹp.', 'career': 'Nghệ thuật, quảng cáo, trang trí tốt.'}}, 'Sơn Địa Bác': {'id': 23, 'vn_name': 'Sơn Địa Bác', 'zh_name': '剥', 'symbol': '䷖', 'binary': '000001', 'upper': 'Cấn', 'lower': 'Khôn', 'upper_el': 'Thổ', 'lower_el': 'Thổ', 'quai_tu_zh': '不利有攸往。', 'quai_tu_vn': 'Bất lợi hữu du vãng — Bóc lột, sụp đổ, tan rã', 'thoan_truyen_zh': '剥，剥也，柔变刚也。“不利有攸往”，小人长也。顺而止之，观象也；君子尚消息盈虚，天行也。', 'dai_tuong_zh': '山附于地，剥。上以厚下安宅。', 'dai_tuong_vn': 'Núi trên đất mỏng, quân tử dày người dưới an nhà', 'y_nghia_vn': 'Sụp đổ, tan rã, hao mòn, tiểu nhân thắng thế', 'loi_khuyen_vn': 'Kiên nhẫn chịu đựng, không hành động, chờ vận mới', 'cat_hung': 'HUNG', 'tap_quai_zh': '爛也', 'tu_quai_zh': '致飾然後亨則盡矣，剝者剝也', 'gaodao_zh': "剥卦象征剥落衰败，坤地承艮山。'剥不利有攸往'，剥以辨幽明消不可不盈。问事运势下滑，宜保守谨慎。", 'gaodao_en': 'Splitting Apart—no benefit in movement. The mountain rests on the Earth, being gradually undermined. This hexagram indicates a time when inferior forces are rising and superior forces are receding. Do not try to advance; guard what remains and wait for the turning point. The dark returns to the light.', 'topics_vn': {'fortune': 'Đại hung. Không nên làm gì lớn.', 'wish': 'Thất bại.', 'love': 'Bị phản bội, chia ly.', 'family': 'Gia đạo sa sút.', 'sickness': 'Bệnh nặng, cơ thể suy kiệt.', 'lost_item': 'Đã mất hẳn, hoặc bị hỏng nát.', 'career': 'Phá sản, mất chức.'}}, 'Địa Lôi Phục': {'id': 24, 'vn_name': 'Địa Lôi Phục', 'zh_name': '复', 'symbol': '䷗', 'binary': '100000', 'upper': 'Khôn', 'lower': 'Chấn', 'upper_el': 'Thổ', 'lower_el': 'Mộc', 'quai_tu_zh': '亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。', 'quai_tu_vn': 'Hanh, xuất nhập vô tật — Trở lại, hồi phục, chu kỳ mới', 'thoan_truyen_zh': '“复，亨”；刚反。动而以顺行，是以“出入无疾，朋来无咎”。“反复其道，七日来复”，天行也。“利有攸往”，刚长也。复，其见天地之心乎？', 'dai_tuong_zh': '雷在地中，复。先王以至日闭关，商旅不行，后不省方。', 'dai_tuong_vn': 'Sấm trong đất, tiên vương chí nhật bế quan', 'y_nghia_vn': 'Trở lại, hồi phục, khởi đầu mới sau suy thoái', 'loi_khuyen_vn': 'Bắt đầu lại từ nhỏ, kiên nhẫn phục hồi', 'cat_hung': 'CÁT', 'tap_quai_zh': '反也', 'tu_quai_zh': '物不可以終盡剝，窮上反下', 'gaodao_zh': "复卦象征回复复兴，震雷出于坤地。'复亨，七日来复'，反复其道天行也。复见天地之心。问事运势将转好，宜把握时机。", 'gaodao_en': 'Return—success through the turning point. Thunder within the Earth returns to movement. This hexagram indicates the return of positive forces after a period of decline. The cycle completes in seven days. The light returns; this is the heart of Heaven and Earth. Success comes through catching the turning tide.', 'topics_vn': {'fortune': 'Cát. Mọi việc dần tốt lên từ đáy.', 'wish': 'Cơ hội thứ hai.', 'love': 'Gương vỡ lại lành, tái hợp.', 'family': 'Đoàn tụ sau xa cách.', 'sickness': 'Bệnh cũ tái phát hoặc đang hồi phục.', 'lost_item': 'Tự nhiên tìm thấy hoặc người cầm trả lại.', 'career': 'Khôi phục vị trí cũ, quay lại nghề cũ.'}}, 'Thiên Lôi Vô Vọng': {'id': 25, 'vn_name': 'Thiên Lôi Vô Vọng', 'zh_name': '无妄', 'symbol': '䷘', 'binary': '100111', 'upper': 'Càn', 'lower': 'Chấn', 'upper_el': 'Kim', 'lower_el': 'Mộc', 'quai_tu_zh': '元亨利贞。其匪正有眚，不利有攸往。', 'quai_tu_vn': 'Nguyên hanh lợi trinh — Không sai lầm, thuận theo tự nhiên', 'thoan_truyen_zh': '无妄，刚自外来，而为主于内。动而健，刚中而应；大“亨”以正，天之命也。“其匪正有眚，不利有攸往”，无妄之往，何之矣？天命不祐，行矣哉？', 'dai_tuong_zh': '天下雷行，物与无妄。先王以茂对时，育万物。', 'dai_tuong_vn': 'Dưới trời có sấm, vạn vật thuận tự nhiên', 'y_nghia_vn': 'Chân thành, không giả dối, thuận theo đạo trời', 'loi_khuyen_vn': 'Sống chân thành, đừng toan tính, thuận theo tự nhiên', 'cat_hung': 'CÁT', 'tap_quai_zh': '災也', 'tu_quai_zh': '復則不妄矣', 'gaodao_zh': "无妄卦象真实自然，震雷上动。'元亨利贞，其匪正有眚'，天下雷行，万物皆惊，真实不虚也。妄言祸至，无妄则福随。问事宜真诚待人，不可妄为，自有吉祥。", 'gaodao_en': 'Without falsehood—supreme success. Thunder moves under Heaven, startling all things into authenticity. Success comes through sincerity and natural action. Deception or calculated manipulation brings calamity. Remain true to your nature and circumstances will align favorably.', 'topics_vn': {'fortune': 'Bình thường nếu giữ đạo lý. Làm sai gặp họa.', 'wish': 'Không nên cưỡng cầu.', 'love': 'Đừng toan tính, hãy chân thành.', 'family': 'Có chuyện bất ngờ xảy ra.', 'sickness': 'Bệnh lạ, tai nạn bất ngờ.', 'lost_item': 'Bị cầm nhầm, khó tìm.', 'career': 'Làm việc chân chính thì bền.'}}, 'Sơn Thiên Đại Súc': {'id': 26, 'vn_name': 'Sơn Thiên Đại Súc', 'zh_name': '大畜', 'symbol': '䷙', 'binary': '111001', 'upper': 'Cấn', 'lower': 'Càn', 'upper_el': 'Thổ', 'lower_el': 'Kim', 'quai_tu_zh': '利贞，不家食，吉；利涉大川。', 'quai_tu_vn': 'Lợi trinh, bất gia thực cát — Tích lũy lớn, nuôi hiền tài', 'thoan_truyen_zh': '大畜，刚健笃实辉光，日新其德；刚上而尚贤，能止健，大正也。“不家食，吉”，养贤也。“利涉大川”，应乎天也。', 'dai_tuong_zh': '天在山中，大畜。君子以多识前言往行，以畜其德。', 'dai_tuong_vn': 'Trời trong núi, quân tử đa thức tiền ngôn vãng hạnh', 'y_nghia_vn': 'Tích lũy lớn, nuôi dưỡng tài năng, kiềm chế sức mạnh', 'loi_khuyen_vn': 'Tích lũy tri thức và tài lực, nuôi chí lớn', 'cat_hung': 'ĐẠI CÁT', 'tap_quai_zh': '時也', 'tu_quai_zh': '有無妄，物然後可畜', 'gaodao_zh': "大畜卦象征大积蓄聚，乾刚畜于艮山。'大畜利贞，不家食吉利涉大川'。刚健笃实辉光，日新其德。问事积蓄丰厚，宜待机而动。", 'gaodao_en': 'The Taming Power of the Great—benefit through restraint and storage. Heaven within the mountain holds vast power. This hexagram indicates a time of great accumulation and potential that is held in reserve. Do not consume resources at home; rather, store them for great undertakings.', 'topics_vn': {'fortune': 'Cát. Tiền tài danh vọng đều có.', 'wish': 'Thành công lớn.', 'love': 'Tình yêu bền vững, gia đình môn đăng hộ đối.', 'family': 'Giàu có, con cái thành đạt.', 'sickness': 'Bệnh tích tụ lâu ngày, khối u.', 'lost_item': 'Ở trong kho, tủ, nơi chứa đồ.', 'career': 'Quản lý kho bãi, ngân hàng, giáo dục.'}}, 'Sơn Lôi Di': {'id': 27, 'vn_name': 'Sơn Lôi Di', 'zh_name': '颐', 'symbol': '䷚', 'binary': '100001', 'upper': 'Cấn', 'lower': 'Chấn', 'upper_el': 'Thổ', 'lower_el': 'Mộc', 'quai_tu_zh': '贞吉，观颐，自求口实。', 'quai_tu_vn': 'Trinh cát, quan di tự cầu khẩu thực — Nuôi dưỡng, ăn uống', 'thoan_truyen_zh': '颐，“贞吉”，养正则吉也。“观颐”，观其所养也。“自求口实”，观其自养也。天地养万物，圣人养贤以及万民。颐之时，义大矣哉！', 'dai_tuong_zh': '山下有雷，颐。君子以慎言语，节饮食。', 'dai_tuong_vn': 'Dưới núi có sấm, quân tử thận ngôn ngữ tiết ẩm thực', 'y_nghia_vn': 'Nuôi dưỡng thân tâm, ăn uống, lời nói cẩn thận', 'loi_khuyen_vn': 'Cẩn thận lời nói và ăn uống, nuôi dưỡng đúng cách', 'cat_hung': 'BÌNH', 'tap_quai_zh': '養正也', 'tu_quai_zh': '物畜然後可養，頤者養也', 'gaodao_zh': "颐卦象征颐养修养，震雷动于艮山。'颐贞吉，养正则吉'。天地养万物，圣人养贤以及万民。问事宜注重修养，保重身体。", 'gaodao_en': 'The Corners of the Mouth—perseverance brings good fortune. Thunder in the mountain stimulates nourishment. This hexagram emphasizes proper nourishment of self and others. Heaven and Earth nourish all things; the wise person nourishes the wise to reach the people. Attention to health and proper speech brings benefit.', 'topics_vn': {'fortune': 'Cát hung tùy lời nói và việc làm.', 'wish': 'Thành công nếu biết chăm sóc, nuôi dưỡng.', 'love': 'Quan tâm chăm sóc nhau qua ăn uống.', 'family': 'Sum họp ăn uống.', 'sickness': 'Bệnh miệng, dạ dày, tiêu hóa.', 'lost_item': 'Tìm ở nhà bếp, phòng ăn.', 'career': 'Ẩm thực, giáo dục, chăn nuôi.'}}, 'Trạch Phong Đại Quá': {'id': 28, 'vn_name': 'Trạch Phong Đại Quá', 'zh_name': '大过', 'symbol': '䷛', 'binary': '011110', 'upper': 'Đoài', 'lower': 'Tốn', 'upper_el': 'Kim', 'lower_el': 'Mộc', 'quai_tu_zh': '栋桡；利有攸往，亨。', 'quai_tu_vn': 'Đống nạo, lợi hữu du vãng — Cột kèo yếu, quá tải', 'thoan_truyen_zh': '“大过”，大者过也。栋桡，本末弱也。刚过而中，巽而说行，“利有攸往”，乃“亨”。“大过”之时大矣哉！', 'dai_tuong_zh': '泽灭木，大过；君子以独立不惧，遁世无闷。', 'dai_tuong_vn': 'Đầm ngập cây, quân tử độc lập bất cụ', 'y_nghia_vn': 'Quá tải, vượt giới hạn, áp lực quá lớn', 'loi_khuyen_vn': 'Hành động táo bạo khi cần, nhưng cẩn thận quá tải', 'cat_hung': 'HUNG', 'tap_quai_zh': '顛也', 'tu_quai_zh': '不養則不可動', 'gaodao_zh': "大过卦象征重大越轨，巽风入兑泽。'大过栋桡，利有攸往亨'。泽灭木，栋不可不刚。独立不惧，遁世无闷。问事有重大变化，需谨慎果断，可成大业。", 'gaodao_en': 'Preponderance of the Great—the ridgepole sags under excessive weight. The lake overflows the wood. This hexagram indicates a situation of extraordinary pressure requiring extraordinary measures. While the challenge is great, careful, bold action can accomplish significant results. Stand independent but not isolated.', 'topics_vn': {'fortune': 'Hung. Áp lực lớn, dễ gãy đổ.', 'wish': 'Quá sức, khó thành.', 'love': 'Tình yêu chênh lệch tuổi tác/địa vị quá lớn.', 'family': 'Gánh vác nợ nần, lo âu.', 'sickness': 'Bệnh nặng, đột quỵ, gan thận.', 'lost_item': 'Bị đè lấp, khó tìm.', 'career': 'Đảm nhận việc quá sức, rủi ro cao.'}}, 'Khảm Vi Thủy': {'id': 29, 'vn_name': 'Khảm Vi Thủy', 'zh_name': '习坎', 'symbol': '䷜', 'binary': '010010', 'upper': 'Khảm', 'lower': 'Khảm', 'upper_el': 'Thủy', 'lower_el': 'Thủy', 'quai_tu_zh': '有孚，维心亨。行有尚。', 'quai_tu_vn': 'Tập Khảm hữu phu, duy tâm hanh — Nước chảy liên tiếp, hiểm', 'thoan_truyen_zh': '“习坎”，重险也。水流而不盈，行险而不失其信。“维心亨”，乃以刚中也。“行有尚”，往有功也。天险，不可升也。地险，山川丘陵也。王公设险，以守其国。险之时用大矣哉！', 'dai_tuong_zh': '水洊至，习坎。君子以常德行，习教事。', 'dai_tuong_vn': 'Nước chảy mãi, quân tử dùng đức hạnh hằng ngày', 'y_nghia_vn': 'Nguy hiểm chồng chất, cần giữ tâm chính, vượt khó', 'loi_khuyen_vn': 'Kiên trì vượt khó, giữ lòng thành, đừng sợ hãi', 'cat_hung': 'HUNG', 'tap_quai_zh': '下也', 'tu_quai_zh': '物不可以終過，坎者陷也', 'gaodao_zh': "坎卦象征险陷困难，坎水相重。'习坎有孚维心亨，行有尚'，水流而不盈行险而不失其信。问事正处于困难时期，需要谨慎。", 'gaodao_en': 'The Abysmal—success through repeated challenge. Water doubles itself, flowing through depths. This hexagram indicates times of danger and difficulty that require faith and persistence. While immersed in difficulty, maintain heart and trust. The water flows on, eventually reaching its goal.', 'topics_vn': {'fortune': 'Đại hung. Cẩn thận tai nạn nước lửa.', 'wish': 'Thất bại, gặp nguy hiểm.', 'love': 'Lừa dối, đau khổ, nước mắt.', 'family': 'Chia ly, buồn phiền.', 'sickness': 'Bệnh thận, máu huyết, tai.', 'lost_item': 'Rơi xuống nước/cống, mất hẳn.', 'career': 'Bế tắc, nguy cơ tù tội/phá sản.'}}, 'Ly Vi Hỏa': {'id': 30, 'vn_name': 'Ly Vi Hỏa', 'zh_name': '离', 'symbol': '䷝', 'binary': '101101', 'upper': 'Ly', 'lower': 'Ly', 'upper_el': 'Hỏa', 'lower_el': 'Hỏa', 'quai_tu_zh': '利贞，亨。畜牝牛，吉。', 'quai_tu_vn': 'Lợi trinh, hanh — Bám vào cái đúng, sáng suốt', 'thoan_truyen_zh': '离，丽也；日月丽乎天，百谷草木丽乎土。重明以丽乎正，乃化成天下。柔丽乎中正，故“亨”，是以“畜牝牛，吉”也。', 'dai_tuong_zh': '明两作，离。大人以继明照于四方。', 'dai_tuong_vn': 'Sáng lặp lại, đại nhân nối sáng thiên hạ', 'y_nghia_vn': 'Sáng suốt, phụ thuộc, bám vào chính đạo', 'loi_khuyen_vn': 'Sáng suốt, minh bạch, bám vào điều đúng đắn', 'cat_hung': 'CÁT', 'tap_quai_zh': '上也', 'tu_quai_zh': '陷必有所麗，離者麗也', 'gaodao_zh': "离卦象征光明依附，离火相重。'离利贞亨畜牝牛吉'，火体虚而形丽，万物皆相见。问事前途光明，但需有所依附。柔顺中正则吉。", 'gaodao_en': 'The Clinging—success through perseverance and attachment. Fire doubles itself, illuminating all things. This hexagram indicates dependence and attachment, like fire clinging to fuel. Success requires proper attachment—to principles, to wise leaders, to what nourishes. Cultivate the receptive, yielding strength of the cow.', 'topics_vn': {'fortune': 'Trung bình. Tốt nếu biết dựa vào người tài.', 'wish': 'Thành công nhờ sự giúp đỡ.', 'love': 'Nồng nhiệt nhưng dễ tàn, hay ghen.', 'family': 'Vẻ vang nhưng nội bộ nóng nảy.', 'sickness': 'Bệnh mắt, tim mạch, sốt cao.', 'lost_item': 'Tìm thấy ở hướng Nam, nơi sáng.', 'career': 'Văn hóa, nghệ thuật, cần người đỡ đầu.'}}, 'Trạch Sơn Hàm': {'id': 31, 'vn_name': 'Trạch Sơn Hàm', 'zh_name': '咸', 'symbol': '䷞', 'binary': '001110', 'upper': 'Đoài', 'lower': 'Cấn', 'upper_el': 'Kim', 'lower_el': 'Thổ', 'quai_tu_zh': '亨，利贞。取女吉。', 'quai_tu_vn': 'Hanh lợi trinh, thủ nữ cát — Cảm ứng, hôn nhân tốt', 'thoan_truyen_zh': '咸，感也。柔上而刚下，二气感应以相与。止而说，男下女，是以“亨，利贞。取女吉”也。天地感而万物化生，圣人感人心而天下和平。观其所感，而天地万物之情可见矣！', 'dai_tuong_zh': '山上有泽，咸。君子以虚受人。', 'dai_tuong_vn': 'Trên núi có đầm, quân tử hư tâm thụ nhân', 'y_nghia_vn': 'Cảm ứng, thu hút, tình cảm, hôn nhân', 'loi_khuyen_vn': 'Mở lòng đón nhận, chân thành trong tình cảm', 'cat_hung': 'CÁT', 'tap_quai_zh': '速也', 'tu_quai_zh': '有天地然後有萬物...有男女然後有夫婦', 'gaodao_zh': "咸卦象征相互感应，艮少男悦兑少女。'咸亨利贞取女吉'，柔上而刚下，二气感应以相与。咸主感应，感而遂通。君子以虚受人。问事人际关系良好，感情融洽。", 'gaodao_en': 'Influence—pervasive, penetrating influence brings success. The mountain is receptive to the lake, creating mutual resonance. This hexagram indicates successful relationships based on genuine attraction and open receptivity. The superior person allows themselves to be influenced, remaining open and empty to receive.', 'topics_vn': {'fortune': 'Cát. Nhân duyên tốt.', 'wish': 'Thành công nhanh chóng.', 'love': 'Tình yêu sét đánh, cưới xin thuận lợi.', 'family': 'Hòa thuận, vui vẻ.', 'sickness': 'Bệnh lây nhiễm, cảm cúm, chân.', 'lost_item': 'Tìm thấy nhờ linh tính mách bảo.', 'career': 'Ngoại giao, tiếp thị, nghệ thuật.'}}, 'Lôi Phong Hằng': {'id': 32, 'vn_name': 'Lôi Phong Hằng', 'zh_name': '恒', 'symbol': '䷟', 'binary': '011100', 'upper': 'Chấn', 'lower': 'Tốn', 'upper_el': 'Mộc', 'lower_el': 'Mộc', 'quai_tu_zh': '亨，无咎，利贞，利有攸往。', 'quai_tu_vn': 'Hanh vô cữu, lợi trinh — Bền bỉ lâu dài, kiên định', 'thoan_truyen_zh': '', 'dai_tuong_zh': '雷风，恒。君子以立不易方。', 'dai_tuong_vn': 'Sấm gió cùng nhau, quân tử lập bất dịch phương', 'y_nghia_vn': 'Bền bỉ, kiên định, hằng tâm, lâu dài', 'loi_khuyen_vn': 'Giữ vững lập trường, kiên trì không thay đổi', 'cat_hung': 'CÁT', 'tap_quai_zh': '久也', 'tu_quai_zh': '夫婦之道不可以不久也，恒者久也', 'gaodao_zh': "恒卦象征恒久稳定，巽风从震雷。'恒亨无咎，利贞利有攸往'，刚上柔下雷风恒。问事宜持之以恒，坚持不懈。", 'gaodao_en': 'Duration—success without blame through perseverance. Thunder and wind create lasting movement. This hexagram indicates the power of persistence and stable habits. Success comes through consistency, not sudden effort. Proper relationships are based on lasting principles that endure through all changes.', 'topics_vn': {'fortune': 'Cát. Lợi về lâu dài.', 'wish': 'Thành công nhưng cần kiên trì.', 'love': 'Bền lâu, gắn bó keo sơn.', 'family': 'Ổn định, bình an.', 'sickness': 'Bệnh mãn tính, dai dẳng.', 'lost_item': 'Tìm thấy ở chỗ cũ, không mất đi đâu.', 'career': 'Công việc ổn định, thâm niên cao.'}}, 'Thiên Sơn Độn': {'id': 33, 'vn_name': 'Thiên Sơn Độn', 'zh_name': '遁', 'symbol': '䷠', 'binary': '001111', 'upper': 'Càn', 'lower': 'Cấn', 'upper_el': 'Kim', 'lower_el': 'Thổ', 'quai_tu_zh': '亨，小利贞。', 'quai_tu_vn': 'Hanh, tiểu lợi trinh — Rút lui đúng lúc', 'thoan_truyen_zh': '“遁，亨”，遁而亨也。刚当位而应，与时行也。“小利贞”，浸而长也。遁之时义大矣哉！', 'dai_tuong_zh': '天下有山，遁。君子以远小人，不恶而严。', 'dai_tuong_vn': 'Dưới trời có núi, quân tử viễn tiểu nhân', 'y_nghia_vn': 'Rút lui, ẩn mình, tránh tiểu nhân, biết lùi', 'loi_khuyen_vn': 'Biết lùi đúng lúc, tránh xa kẻ xấu, bảo toàn', 'cat_hung': 'BÌNH', 'tap_quai_zh': '退也', 'tu_quai_zh': '物不可以久居其所，遯者退也', 'gaodao_zh': "遁卦象征退避隐退，艮山遇乾天。'遁亨小利贞'，天下有山，渐离之象。遯退之时，宜静不宜动，识时务者为俊杰。问事时机不利，宜退守待机。君子以远小人，不恶而严。", 'gaodao_en': 'Retreat—success through timely withdrawal. Heaven above the mountain, gradually distancing. This hexagram indicates a time when withdrawal is wiser than advance. The wise person recognizes when conditions are unfavorable and maintains dignity while creating distance from negative influences.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Lôi Thiên Đại Tráng': {'id': 34, 'vn_name': 'Lôi Thiên Đại Tráng', 'zh_name': '大壮', 'symbol': '䷡', 'binary': '111100', 'upper': 'Chấn', 'lower': 'Càn', 'upper_el': 'Mộc', 'lower_el': 'Kim', 'quai_tu_zh': '利贞。', 'quai_tu_vn': 'Lợi trinh — Sức mạnh lớn, cần chính đáng', 'thoan_truyen_zh': '“大壮”，大者壮也；刚以动，故壮。“大壮，利贞”，大者正也。正大而天地之情可见矣。', 'dai_tuong_zh': '雷在天上，大壮。君子以非礼弗履。', 'dai_tuong_vn': 'Sấm trên trời, quân tử phi lễ bất lý', 'y_nghia_vn': 'Sức mạnh lớn, hùng tráng, cần dùng đúng đắn', 'loi_khuyen_vn': 'Dùng sức mạnh đúng đắn, đừng lạm dụng quyền lực', 'cat_hung': 'CÁT', 'tap_quai_zh': '則止', 'tu_quai_zh': '物不可以終遯', 'gaodao_zh': "大壮卦象征强大盛壮，震雷上鸣。'大壮利贞，大者壮也'，刚以动故壮，雷在天上。问事力量强大，但需谨慎。壮于趾者凶。", 'gaodao_en': 'The Power of the Great—perseverance brings fortune. Thunder in Heaven, powerful and moving. This hexagram indicates great strength and energy, but warns against using force improperly. Power without wisdom leads to misfortune. Restrain the impulse to forcefully advance; true power requires proper timing.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Hỏa Địa Tấn': {'id': 35, 'vn_name': 'Hỏa Địa Tấn', 'zh_name': '晋', 'symbol': '䷢', 'binary': '000101', 'upper': 'Ly', 'lower': 'Khôn', 'upper_el': 'Hỏa', 'lower_el': 'Thổ', 'quai_tu_zh': '康侯用锡马蕃庶，昼日三接。', 'quai_tu_vn': 'Khang hầu dụng tích mã phồn thứ — Tiến lên, thăng tiến', 'thoan_truyen_zh': '晋，进也。明出地上。顺而丽乎大明，柔进而上行，是以“康侯用锡马蕃庶，昼日三接”也。', 'dai_tuong_zh': '明出地上，晋。君子以自昭明德。', 'dai_tuong_vn': 'Mặt trời mọc trên đất, quân tử tự chiếu minh đức', 'y_nghia_vn': 'Tiến bộ, thăng tiến, sáng sủa, phát triển', 'loi_khuyen_vn': 'Tiến lên với đức sáng, phát triển nhanh chóng', 'cat_hung': 'CÁT', 'tap_quai_zh': '晝也', 'tu_quai_zh': '物不可以終壯，晉者進也', 'gaodao_zh': "晋卦象征晋升进步，离明照坤地。'晋康侯用锡马蕃庶，昼日三接'。明出地上，顺而丽乎大明。问事事业将有进展，宜积极进取。", 'gaodao_en': 'Progress—success through advancement. The sun rises over the Earth, illuminating all. This hexagram indicates a time of rapid progress and recognition. The wise person is honored and rewarded multiple times. Success comes through clarifying and illuminating matters while maintaining harmonious relations.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Địa Hỏa Minh Di': {'id': 36, 'vn_name': 'Địa Hỏa Minh Di', 'zh_name': '明夷', 'symbol': '䷣', 'binary': '101000', 'upper': 'Khôn', 'lower': 'Ly', 'upper_el': 'Thổ', 'lower_el': 'Hỏa', 'quai_tu_zh': '利艰贞。', 'quai_tu_vn': 'Lợi gian trinh — Ánh sáng bị che, ẩn nhẫn', 'thoan_truyen_zh': '明入地中，“明夷”。内文明而外柔顺，以蒙大难，文王以之。“利艰贞”，晦其明也；内难而能正其志，箕子以之。', 'dai_tuong_zh': '明入地中，明夷。君子以莅众，用晦而明。', 'dai_tuong_vn': 'Sáng vào trong đất, quân tử dụng hối mà minh', 'y_nghia_vn': 'Bị áp chế, tài năng bị che giấu, ẩn nhẫn', 'loi_khuyen_vn': 'Ẩn nhẫn chờ thời, giấu tài năng, tránh kẻ xấu', 'cat_hung': 'HUNG', 'tap_quai_zh': '誅也', 'tu_quai_zh': '進必有所傷，夷者傷也', 'gaodao_zh': "明夷卦象征光明受伤，离火入坤地。'明夷利艰贞'，明入地中伤则晦，晦则忧忧则用晦而明。问事暂时受挫，需要忍耐。", 'gaodao_en': 'Darkening of the Light—perseverance through difficulty. Fire enters the Earth, its light obscured. This hexagram indicates a time when the bright must suffer injury and hide their light. While the light is darkened, maintain correct principles in adversity. Difficult times eventually pass.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Phong Hỏa Gia Nhân': {'id': 37, 'vn_name': 'Phong Hỏa Gia Nhân', 'zh_name': '家人', 'symbol': '䷤', 'binary': '101011', 'upper': 'Tốn', 'lower': 'Ly', 'upper_el': 'Mộc', 'lower_el': 'Hỏa', 'quai_tu_zh': '利女贞。', 'quai_tu_vn': 'Lợi nữ trinh — Gia đình hòa thuận, đàn bà chính', 'thoan_truyen_zh': '家人，女正位乎内，男正位乎外；男女正，天地之大义也。家人有严君焉，父母之谓也。父父，子子，兄兄，弟弟，夫夫，妇妇，而家道正，正家而天下定矣。', 'dai_tuong_zh': '风自火出，家人。君子以言有物而行有恒。', 'dai_tuong_vn': 'Gió từ lửa, quân tử ngôn hữu vật hành hữu hằng', 'y_nghia_vn': 'Gia đình, nội trợ, hòa thuận trong nhà', 'loi_khuyen_vn': 'Chú trọng gia đình, lời nói phải có thực, hành vi nhất quán', 'cat_hung': 'CÁT', 'tap_quai_zh': '內也', 'tu_quai_zh': '傷于外者必反於家', 'gaodao_zh': "家人卦象征家庭和睦，离火出于巽风。'家人有严君焉，父母之谓也'。父父子子兄兄弟弟夫夫妇妇而家道正。问事家庭关系和谐，宜重视家庭。", 'gaodao_en': 'The Family—benefit through proper relationships. Wind comes from fire, creating warmth that reaches all. This hexagram emphasizes the importance of family order—fathers fathering, sons sonning, etc. When family relationships are correct, all under Heaven becomes stable.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Hỏa Trạch Khuê': {'id': 38, 'vn_name': 'Hỏa Trạch Khuê', 'zh_name': '睽', 'symbol': '䷥', 'binary': '110101', 'upper': 'Ly', 'lower': 'Đoài', 'upper_el': 'Hỏa', 'lower_el': 'Kim', 'quai_tu_zh': '小事吉。', 'quai_tu_vn': 'Tiểu sự cát — Đối lập, mâu thuẫn, chỉ làm việc nhỏ', 'thoan_truyen_zh': '睽，火动而上，泽动而下；二女同居，其志不同行；说而丽乎明，柔进而上行，得中而应乎刚，是以“小事吉”。天地睽而其事同也，男女睽而其志通也，万物睽而其事类也；睽之时用大矣哉！', 'dai_tuong_zh': '上火下泽，睽；君子以同而异。', 'dai_tuong_vn': 'Lửa trên đầm, quân tử đồng mà dị', 'y_nghia_vn': 'Mâu thuẫn, bất đồng, đối lập nhưng bổ sung', 'loi_khuyen_vn': 'Hòa giải mâu thuẫn, tìm điểm chung trong khác biệt', 'cat_hung': 'BÌNH', 'tap_quai_zh': '外也', 'tu_quai_zh': '家道窮必乖，睽者乖也', 'gaodao_zh': "睽卦象征乖离不合，离火焚兑泽。'睽小事吉'，异中同也，同中有睽。遇主于巷无咎。问事人际关系有隔阂，需沟通调和。", 'gaodao_en': 'Opposition—small matters bring success. Fire moves away from the lake, creating separation. This hexagram indicates a time of divergence and misunderstanding. While differences exist, finding common ground in small things leads to good fortune. Meeting the leader in the byway is not a mistake.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Thủy Sơn Kiển': {'id': 39, 'vn_name': 'Thủy Sơn Kiển', 'zh_name': '蹇', 'symbol': '䷦', 'binary': '001010', 'upper': 'Khảm', 'lower': 'Cấn', 'upper_el': 'Thủy', 'lower_el': 'Thổ', 'quai_tu_zh': '利西南，不利东北；利见大人，贞吉。', 'quai_tu_vn': 'Lợi Tây Nam, bất lợi Đông Bắc — Khó khăn, hiểm trở', 'thoan_truyen_zh': '蹇，难也，险在前也；见险而能止，知矣哉！“蹇，利西南”，往得中也；“不利东北”，其道穷也。“利见大人”，往有功也；当位“贞吉”，以正邦也。蹇之时用大矣哉！', 'dai_tuong_zh': '山上有水，蹇。君子以反身修德。', 'dai_tuong_vn': 'Trên núi có nước, quân tử phản thân tu đức', 'y_nghia_vn': 'Khó khăn, trở ngại, cần tìm đường tránh', 'loi_khuyen_vn': 'Tránh khó khăn, đi đường vòng, tu sửa bản thân', 'cat_hung': 'HUNG', 'tap_quai_zh': '難也', 'tu_quai_zh': '乖必有難，蹇者難也', 'gaodao_zh': "蹇卦象征艰难险阻，艮山阻坎水。'蹇利西南不利东北'，见险而能止知矣哉。问事前行受阻，需要谨慎。", 'gaodao_en': 'Obstruction—benefit in the southwest, not in the northeast. Water on the mountain is blocked. This hexagram indicates a time when progress is difficult and dangerous. It is wise to stop when seeing danger. Retreat to favorable conditions rather than forcing advance against obstruction.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Lôi Thủy Giải': {'id': 40, 'vn_name': 'Lôi Thủy Giải', 'zh_name': '解', 'symbol': '䷧', 'binary': '010100', 'upper': 'Chấn', 'lower': 'Khảm', 'upper_el': 'Mộc', 'lower_el': 'Thủy', 'quai_tu_zh': '利西南。无所往，其来复吉。有攸往，夙吉。', 'quai_tu_vn': 'Lợi Tây Nam, vô sở vãng — Thoát khó, giải thoát', 'thoan_truyen_zh': '解，险以动，动而免乎险，解。“解，利西南”，往得众也；“其来复吉”，乃得中也；“有攸往，夙吉”，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之时义大矣哉！', 'dai_tuong_zh': '雷雨作，解。君子以赦过宥罪。', 'dai_tuong_vn': 'Sấm mưa nổi, quân tử xá lỗi giảm tội', 'y_nghia_vn': 'Giải thoát, thoát khỏi khó khăn, tha thứ', 'loi_khuyen_vn': 'Tha thứ, giải quyết nhanh, đừng chần chừ sau khi thoát khó', 'cat_hung': 'CÁT', 'tap_quai_zh': '緩也', 'tu_quai_zh': '物不可以終難，解者緩也', 'gaodao_zh': "解卦象征解除困难，坎险遇震雷。'解利西南无所往，其来复吉'，雷雨作解，险难消散。问事困难将解除，运势好转。", 'gaodao_en': 'Deliverance—benefit in the southwest; returning brings good fortune. Thunder and rain disperse difficulties. This hexagram indicates a time when obstacles are removed and dangers dissolve. Action is now appropriate to clear remaining debris from past difficulties. The Way opens again.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Sơn Trạch Tổn': {'id': 41, 'vn_name': 'Sơn Trạch Tổn', 'zh_name': '损', 'symbol': '䷨', 'binary': '110001', 'upper': 'Cấn', 'lower': 'Đoài', 'upper_el': 'Thổ', 'lower_el': 'Kim', 'quai_tu_zh': '有孚，元吉，无咎，可贞，利有攸往。曷之用？二簋可用享。', 'quai_tu_vn': 'Hữu phu, nguyên cát — Giảm bớt có lòng thành là tốt', 'thoan_truyen_zh': '损，损下益上，其道上行。损而“有孚，元吉，无咎，可贞，利有攸往。曷之用？二簋可用享。”二簋应有时，损刚益柔有时，损益盈虚，与时偕行。', 'dai_tuong_zh': '山下有泽，损。君子以惩忿窒欲。', 'dai_tuong_vn': 'Dưới núi có đầm, quân tử trừng phẫn trật dục', 'y_nghia_vn': 'Giảm bớt, hy sinh, tiết kiệm, tổn trên lợi dưới', 'loi_khuyen_vn': 'Chấp nhận hy sinh ngắn hạn để được lợi lâu dài', 'cat_hung': 'BÌNH', 'tap_quai_zh': '盛衰之始也', 'tu_quai_zh': '緩必有所失', 'gaodao_zh': "损卦象征减损付出，兑泽入艮山。'损而有孚元亨利贞'，损下益上其道上行。问事需有所付出，但终有回报。", 'gaodao_en': 'Decrease—supreme success through sacrifice. The lake decreases to nourish the mountain. This hexagram indicates that decrease of the lower to benefit the upper brings success. Willing sacrifice and acceptance of loss create the conditions for future gain. What is given up in faith returns multiplied.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Phong Lôi Ích': {'id': 42, 'vn_name': 'Phong Lôi Ích', 'zh_name': '益', 'symbol': '䷩', 'binary': '100011', 'upper': 'Tốn', 'lower': 'Chấn', 'upper_el': 'Mộc', 'lower_el': 'Mộc', 'quai_tu_zh': '利有攸往，利涉大川。', 'quai_tu_vn': 'Lợi hữu du vãng, lợi thiệp đại xuyên — Tăng thêm, thu được lợi', 'thoan_truyen_zh': '益，损上益下，民说无疆；自上下下，其道大光。“利有攸往”，中正有庆；“利涉大川”，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。', 'dai_tuong_zh': '风雷，益。君子以见善则迁，有过则改。', 'dai_tuong_vn': 'Gió sấm cùng nhau, quân tử thấy thiện liền làm', 'y_nghia_vn': 'Tăng thêm, lợi ích, phát triển, bề trên giúp bề dưới', 'loi_khuyen_vn': 'Hành động khi có cơ hội, làm việc thiện, giúp đỡ người', 'cat_hung': 'ĐẠI CÁT', 'tap_quai_zh': '盛衰之始也', 'tu_quai_zh': '損而不已必益', 'gaodao_zh': "益卦象征增益受益，震雷加于巽风。'益利有攸往，利涉大川'，风雷益，损益盈虚与时皆行。问事将有收益，宜积极进取。", 'gaodao_en': "Increase—benefit through movement and action. Wind and thunder increase each other's power. This hexagram indicates a time when it is beneficial to undertake great endeavors and cross great waters. Benefits flow to those who act generously and correctly with their increase.", 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Trạch Thiên Quải': {'id': 43, 'vn_name': 'Trạch Thiên Quải', 'zh_name': '夬', 'symbol': '䷪', 'binary': '111110', 'upper': 'Đoài', 'lower': 'Càn', 'upper_el': 'Kim', 'lower_el': 'Kim', 'quai_tu_zh': '扬于王庭，孚号有厉；告自邑，不利即戎，利有攸往。', 'quai_tu_vn': 'Dương vu vương đình — Quyết đoán, loại bỏ kẻ xấu', 'thoan_truyen_zh': '夬，决也，刚决柔也；健而说，决而和。“扬于王庭”，柔乘五刚也；“孚号有厉”，其危乃光也；“告自邑，不利即戎”，所尚乃穷也；“利有攸往”，刚长乃终也。', 'dai_tuong_zh': '泽上于天，夬。君子以施禄及下，居德则忌。', 'dai_tuong_vn': 'Đầm trên trời, quân tử thí lộc cập hạ', 'y_nghia_vn': 'Quyết đoán, đoạn tuyệt, loại bỏ cái xấu', 'loi_khuyen_vn': 'Quyết đoán loại bỏ xấu, nhưng cẩn thận phản ứng ngược', 'cat_hung': 'BÌNH', 'tap_quai_zh': '決也，剛決柔也', 'tu_quai_zh': '益而不已必決，夬者決也', 'gaodao_zh': "夬卦象征决断清除，乾刚决兑柔。'夬扬于王庭，孚号有厉'，刚决柔也，健而说决而和。泽上于天，决之将出。问事需果断决策，清除障碍。利有攸往，终有凶也。", 'gaodao_en': 'Break-through—resolutely bringing the matter before the court. The lake rises to Heaven, about to break through. This hexagram represents the need for decisive action to remove obstacles. While determination brings progress, be mindful that excessive force may lead to future difficulties.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Thiên Phong Cấu': {'id': 44, 'vn_name': 'Thiên Phong Cấu', 'zh_name': '姤', 'symbol': '䷫', 'binary': '011111', 'upper': 'Càn', 'lower': 'Tốn', 'upper_el': 'Kim', 'lower_el': 'Mộc', 'quai_tu_zh': '女壮，勿用取女。', 'quai_tu_vn': 'Nữ tráng, vật dụng thủ nữ — Gặp gỡ bất ngờ, đàn bà mạnh', 'thoan_truyen_zh': '姤，遇也，柔遇刚也。“勿用取女”，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。姤之时义大矣哉！', 'dai_tuong_zh': '天下有风，姤。后以施命诰四方。', 'dai_tuong_vn': 'Dưới trời có gió, hậu thi mệnh cáo tứ phương', 'y_nghia_vn': 'Gặp gỡ bất ngờ, hội ngộ, cần cẩn thận', 'loi_khuyen_vn': 'Cẩn thận với gặp gỡ bất ngờ, đừng quá tin', 'cat_hung': 'BÌNH', 'tap_quai_zh': '遇也，柔遇剛也', 'tu_quai_zh': '決必有遇，姤者遇也', 'gaodao_zh': "姤卦象征不期而遇，乾刚遇巽柔。'姤女壮勿用取女'，阴遇阳也，天地相遇品物咸章。鱼沉于渊，五行之类。问事有意外机遇，人际关系变化。宜谨慎防微杜渐。", 'gaodao_en': 'Coming to meet—unexpected encounters. The strong meets the yielding. This hexagram warns of chance meetings that may lead to complications, particularly in relationships. While opportunities arise unexpectedly, caution is advised—inspect carefully before committing.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Trạch Địa Tụy': {'id': 45, 'vn_name': 'Trạch Địa Tụy', 'zh_name': '萃', 'symbol': '䷬', 'binary': '000110', 'upper': 'Đoài', 'lower': 'Khôn', 'upper_el': 'Kim', 'lower_el': 'Thổ', 'quai_tu_zh': '亨，王假有庙，利见大人，亨，利贞；用大牲吉，利有攸往。', 'quai_tu_vn': 'Hanh, vương cách hữu miếu — Tụ họp, tập trung', 'thoan_truyen_zh': '萃，聚也；顺以说，刚中而应，故聚也。“王假有庙”，致孝享也；“利见大人，亨”，聚以正也；“用大牲吉，利有攸往”，顺天命也。观其所聚，而天地万物之情可见矣。', 'dai_tuong_zh': '泽上于地，萃。君子以除戎器，戒不虞。', 'dai_tuong_vn': 'Đầm trên đất, quân tử trừ nhung khí giới phòng bất trắc', 'y_nghia_vn': 'Tụ họp, tập hợp lực lượng, đoàn kết', 'loi_khuyen_vn': 'Tập hợp lực lượng, chuẩn bị phòng ngừa bất trắc', 'cat_hung': 'CÁT', 'tap_quai_zh': '聚也', 'tu_quai_zh': '物相遇而後聚，萃者聚也', 'gaodao_zh': "萃卦象征聚集聚合，坤地承兑泽。'萃王假有庙，利见大人亨'。聚以正者吉，逆命者凶。萃如嗟如无攸利。问事人缘聚合，宜合作共事。", 'gaodao_en': 'Gathering Together—success through assembly. The Earth receives the lake, collecting waters. This hexagram indicates benefits that come through rightful assembly and congregation. The king approaches the temple—proper gathering around a center of value brings benefit through meeting with great persons.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Địa Phong Thăng': {'id': 46, 'vn_name': 'Địa Phong Thăng', 'zh_name': '升', 'symbol': '䷭', 'binary': '011000', 'upper': 'Khôn', 'lower': 'Tốn', 'upper_el': 'Thổ', 'lower_el': 'Mộc', 'quai_tu_zh': '元亨，用见大人，勿恤。南征吉。', 'quai_tu_vn': 'Nguyên hanh, dụng kiến đại nhân — Đi lên, thăng tiến', 'thoan_truyen_zh': '柔以时升，巽而顺，刚中而应，是以大亨。“用见大人，勿恤”，有庆也；“南征吉”，志行也。', 'dai_tuong_zh': '地中生木，升。君子以顺德，积小以高大。', 'dai_tuong_vn': 'Cây mọc trong đất, quân tử thuận đức tích tiểu thành cao', 'y_nghia_vn': 'Thăng tiến, đi lên, phát triển từ từ vững chắc', 'loi_khuyen_vn': 'Phát triển từ từ, vững bước đi lên, tìm quý nhân', 'cat_hung': 'ĐẠI CÁT', 'tap_quai_zh': '不來也', 'tu_quai_zh': '聚而上者謂之升', 'gaodao_zh': "升卦象征上升发展，巽风入坤地。'升元亨，用见大人勿恤，南征吉'。问事事业上升，前景光明。", 'gaodao_en': 'Pushing Upward—supreme success. Wood within the Earth pushes upward, growing. This hexagram indicates a time of steady ascent and progress. Do not worry; meet with great persons. The south (direction of light) brings good fortune. Success comes through patient, persistent upward movement.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Trạch Thủy Khốn': {'id': 47, 'vn_name': 'Trạch Thủy Khốn', 'zh_name': '困', 'symbol': '䷮', 'binary': '010110', 'upper': 'Đoài', 'lower': 'Khảm', 'upper_el': 'Kim', 'lower_el': 'Thủy', 'quai_tu_zh': '亨。贞，大人吉，无咎；有言不信。', 'quai_tu_vn': 'Hanh, trinh đại nhân cát — Khốn cùng nhưng giữ chí', 'thoan_truyen_zh': '困，刚掩也。险以说，困而不失其所“亨”，其唯君子乎！“贞，大人吉”，以刚中也；“有言不信”，尚口乃穷也。', 'dai_tuong_zh': '泽无水，困。君子以致命遂志。', 'dai_tuong_vn': 'Đầm không có nước, quân tử trí mệnh toại chí', 'y_nghia_vn': 'Khốn cùng, bế tắc, thiếu thốn, cần giữ chí', 'loi_khuyen_vn': 'Giữ vững ý chí trong khó khăn, chờ cơ hội', 'cat_hung': 'HUNG', 'tap_quai_zh': '相遇也', 'tu_quai_zh': '升而不已必困', 'gaodao_zh': "困卦象征困穷艰难，坎水入兑泽。'困亨贞大人吉无咎'，困而不失其所亨，穷则变通。困于石、据于蒺藜，入宫不见妻皆凶。问事处于困境，需坚持忍耐。", 'gaodao_en': 'Oppression—success through perseverance. The water sinks into the marsh,被困. This hexagram represents hardship and constraint. While the situation is difficult, the superior person preserves their character and finds ways to persevere. Oppression ultimately transforms when one maintains integrity.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Thủy Phong Tỉnh': {'id': 48, 'vn_name': 'Thủy Phong Tỉnh', 'zh_name': '井', 'symbol': '䷯', 'binary': '011010', 'upper': 'Khảm', 'lower': 'Tốn', 'upper_el': 'Thủy', 'lower_el': 'Mộc', 'quai_tu_zh': '改邑不改井，无丧无得，往来井井；汔至，亦未繘井，羸其瓶，凶。', 'quai_tu_vn': 'Cải ấp bất cải tỉnh — Giếng nước không thay đổi, nguồn gốc', 'thoan_truyen_zh': '巽乎水而上水，井；井养而不穷也。“改邑不改井”，乃以刚中也。“汔至，亦未繘井”，未有功也。“羸其瓶”，是以凶也。', 'dai_tuong_zh': '木上有水，井。君子以劳民劝相。', 'dai_tuong_vn': 'Trên cây có nước, quân tử lao dân khuyến tướng', 'y_nghia_vn': 'Nguồn gốc, cội nguồn, nuôi dưỡng không ngừng', 'loi_khuyen_vn': 'Giữ gốc, nuôi dưỡng nguồn lực, phục vụ mọi người', 'cat_hung': 'CÁT', 'tap_quai_zh': '通也', 'tu_quai_zh': '困乎上者必反下', 'gaodao_zh': "井卦象征汲养不变，巽木入坎水。'井改邑不改井，无丧无得'，井养而不穷。问事基础稳固，宜守成。", 'gaodao_en': "The Well—fundamental resource that does not change. Water over wood draws up the well's resources. This hexagram indicates stable, enduring resources that nourish all. Though towns may change, the well remains. Maintain and care for fundamental resources; they provide inexhaustible benefit.", 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Trạch Hỏa Cách': {'id': 49, 'vn_name': 'Trạch Hỏa Cách', 'zh_name': '革', 'symbol': '䷰', 'binary': '101110', 'upper': 'Đoài', 'lower': 'Ly', 'upper_el': 'Kim', 'lower_el': 'Hỏa', 'quai_tu_zh': '巳日乃孚，元亨利贞，悔亡。', 'quai_tu_vn': 'Tị nhật nãi phu — Đến ngày đổi mới mới tin', 'thoan_truyen_zh': '革，水火相息；二女同居，其志不相得，曰革。“巳日乃孚”，革而信之；文明以说，大“亨”以正，革而当，其“悔”乃“亡”。天地革而四时成。汤武革命，顺乎天而应乎人。革之时义大矣哉！', 'dai_tuong_zh': '泽中有火，革。君子以治历明时。', 'dai_tuong_vn': 'Đầm có lửa, quân tử trị lịch minh thời', 'y_nghia_vn': 'Cách mạng, thay đổi, đổi mới, biến cách', 'loi_khuyen_vn': 'Thay đổi khi đúng thời điểm, cải cách mạnh mẽ', 'cat_hung': 'CÁT', 'tap_quai_zh': '去故也', 'tu_quai_zh': '井道不可不革', 'gaodao_zh': "革卦象征变革除旧，离火焚兑泽。'革己日乃孚，元亨利贞悔亡'。革去故而鼎取新，天地革而四时成，汤武革命顺天应人。问事需改革创新，破旧立新。", 'gaodao_en': 'Revolution—transformation occurs when the old is exhausted. Fire in the lake brings change. Just as Heaven and Earth create the four seasons through change, human affairs require periodic renewal. Success comes through timely transformation that responds to genuine need, not forced change.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Hỏa Phong Đỉnh': {'id': 50, 'vn_name': 'Hỏa Phong Đỉnh', 'zh_name': '鼎', 'symbol': '䷱', 'binary': '011101', 'upper': 'Ly', 'lower': 'Tốn', 'upper_el': 'Hỏa', 'lower_el': 'Mộc', 'quai_tu_zh': '元吉，亨。', 'quai_tu_vn': 'Nguyên cát, hanh — Vạc nấu ăn, nuôi hiền', 'thoan_truyen_zh': '鼎，象也。以木巽火，亨饪也。圣人亨以享上帝，而大亨以养圣贤。巽而耳目聪明，柔进而上行，得中而应乎刚，是以元亨。', 'dai_tuong_zh': '木上有火，鼎。君子以正位凝命。', 'dai_tuong_vn': 'Trên cây có lửa, quân tử chính vị ngưng mệnh', 'y_nghia_vn': 'Nuôi dưỡng, chuyển hóa, nấu nướng, văn minh', 'loi_khuyen_vn': 'Chuyển hóa tài nguyên, nuôi dưỡng nhân tài', 'cat_hung': 'ĐẠI CÁT', 'tap_quai_zh': '取新也', 'tu_quai_zh': '革物者莫若鼎', 'gaodao_zh': "鼎卦象征革新稳定，离火入巽风。'鼎元吉亨'，鼎象也，革故鼎新，鼎养神明。问事事业稳固，宜改革创新。", 'gaodao_en': 'The Cauldron—supreme good fortune. Fire enters the wood, cooking and transforming. This hexagram represents stability that contains transformation, like an ancient vessel used for sacred cooking. Nourishing the wise brings fundamental good fortune. A time for innovation within established structures.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Chấn Vi Lôi': {'id': 51, 'vn_name': 'Chấn Vi Lôi', 'zh_name': '震', 'symbol': '䷲', 'binary': '100100', 'upper': 'Chấn', 'lower': 'Chấn', 'upper_el': 'Mộc', 'lower_el': 'Mộc', 'quai_tu_zh': '亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。', 'quai_tu_vn': 'Hanh, sấm đến khiếp khiếp — Sấm lặp gây sợ rồi vui', 'thoan_truyen_zh': '震，亨。“震来虩虩”，恐致福也；“笑言哑哑”，后有则也。“震惊百里”，惊远而惧迩也；出可以守宗庙社稷，以为祭主也。', 'dai_tuong_zh': '洊雷，震。君子以恐惧修省。', 'dai_tuong_vn': 'Sấm nổi liên tiếp, quân tử sợ mà tu sửa', 'y_nghia_vn': 'Chấn động, sợ hãi rồi tỉnh ngộ, thay đổi', 'loi_khuyen_vn': 'Cẩn trọng sửa mình sau chấn động, không hoảng loạn', 'cat_hung': 'BÌNH', 'tap_quai_zh': '起也', 'tu_quai_zh': '主器者莫若長子，震者動也', 'gaodao_zh': "震卦象征震动惊惧，震雷相重。'震亨，震来虩虩笑言哑哑'，震惊百里惊远惧迩。问事会有变动或惊动，但终能吉祥。", 'gaodao_en': 'The Arousing—success through shock and movement. Thunder doubles itself, startling all within a hundred miles. This hexagram indicates sudden change or shock that initially brings fear but ultimately leads to laughter and success. Maintain equanimity during upheavals; they awaken new possibilities.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Cấn Vi Sơn': {'id': 52, 'vn_name': 'Cấn Vi Sơn', 'zh_name': '艮', 'symbol': '䷳', 'binary': '001001', 'upper': 'Cấn', 'lower': 'Cấn', 'upper_el': 'Thổ', 'lower_el': 'Thổ', 'quai_tu_zh': '艮其背，不获其身；行其庭，不见其人，无咎。', 'quai_tu_vn': 'Cấn kỳ bối, bất hoạch kỳ thân — Giữ yên, không thấy thân', 'thoan_truyen_zh': '艮，止也。时止则止，时行则行；动静不失其时，其道光明。艮其止，止其所也。上下敌应，不相与也。是以“不获其身，行其庭，不见其人，无咎”也。', 'dai_tuong_zh': '兼山，艮。君子以思不出其位。', 'dai_tuong_vn': 'Hai núi chồng, quân tử biết dừng đúng lúc', 'y_nghia_vn': 'Dừng lại, tĩnh lặng, biết đủ, ổn định', 'loi_khuyen_vn': 'Biết dừng, biết đủ, tĩnh tâm suy ngẫm', 'cat_hung': 'BÌNH', 'tap_quai_zh': '止也', 'tu_quai_zh': '物不可以終動，止之，艮者止也', 'gaodao_zh': "艮卦象征静止停止，艮山相重。'艮其背不获其身，行其庭不见其人'。止于所当止，动静不失其时。问事宜停止不前，等待时机。", 'gaodao_en': 'Keeping Still—peace through proper stopping. The mountain doubles itself, perfectly still. This hexagram indicates the necessity of keeping still and maintaining proper boundaries. Stop at the right place at the right time. When action is not appropriate, maintaining stillness brings peace.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Phong Sơn Tiệm': {'id': 53, 'vn_name': 'Phong Sơn Tiệm', 'zh_name': '渐', 'symbol': '䷴', 'binary': '001011', 'upper': 'Tốn', 'lower': 'Cấn', 'upper_el': 'Mộc', 'lower_el': 'Thổ', 'quai_tu_zh': '女归吉，利贞。', 'quai_tu_vn': 'Nữ quy cát, lợi trinh — Tiến từ từ, thuận lợi', 'thoan_truyen_zh': '渐之进也，“女归吉”也。进得位，往有功也；进以正，可以正邦也。其位，刚得中也；止而巽，动不穷也。', 'dai_tuong_zh': '山上有木，渐。君子以居贤德善俗。', 'dai_tuong_vn': 'Trên núi có cây, quân tử cư hiền đức thiện tục', 'y_nghia_vn': 'Tiến từ từ, phát triển tuần tự, hôn nhân', 'loi_khuyen_vn': 'Tiến bước từ từ, không vội vàng, phát triển bền vững', 'cat_hung': 'CÁT', 'tap_quai_zh': '女歸待男行也', 'tu_quai_zh': '物不可以終止，漸者進也', 'gaodao_zh': "渐卦象征循序渐进，艮山止巽风。'渐女归吉利贞'，渐进也，进以正可以正邦。问事宜循序渐进，不可急躁。", 'gaodao_en': "Development—success through gradual progress. Wind on the mountain advances tree by tree. This hexagram indicates the beauty of gradual, natural progression, like a maiden's proper marriage. Do not force progress; allow things to unfold in their proper time. Success comes through steady, correct advance.", 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Lôi Trạch Quy Muội': {'id': 54, 'vn_name': 'Lôi Trạch Quy Muội', 'zh_name': '归妹', 'symbol': '䷵', 'binary': '110100', 'upper': 'Chấn', 'lower': 'Đoài', 'upper_el': 'Mộc', 'lower_el': 'Kim', 'quai_tu_zh': '征凶，无攸利。', 'quai_tu_vn': 'Chinh hung, vô du lợi — Gả em gái, bất lợi', 'thoan_truyen_zh': '归妹，天地之大义也。天地不交，而万物不兴。归妹，人之终始也。说以动，所归妹也；“征凶”，位不当也；“无攸利”，柔乘刚也。', 'dai_tuong_zh': '泽上有雷，归妹。君子以永终知敝。', 'dai_tuong_vn': 'Trên đầm có sấm, quân tử dĩ vĩnh chung tri tệ', 'y_nghia_vn': 'Hôn nhân không thuận, quan hệ bất chính, vội vàng', 'loi_khuyen_vn': 'Cẩn thận trong quan hệ, đừng vội vàng kết hợp', 'cat_hung': 'HUNG', 'tap_quai_zh': '女之終也', 'tu_quai_zh': '進必有所歸', 'gaodao_zh': "归妹卦象征婚配归宿，兑少女从震长男。'归妹征凶无攸利'，天地之大义，天地不交则万物不兴。问事将有归宿，宜顺其自然。", 'gaodao_en': 'The Marrying Maiden—undertakings bring misfortune. Thunder over the lake—movement following joy. This hexagram indicates relationships or situations where the proper order is reversed or inappropriate. While unions occur, they may not be fully harmonious. Accept natural outcomes without forcing perfect arrangements.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Lôi Hỏa Phong': {'id': 55, 'vn_name': 'Lôi Hỏa Phong', 'zh_name': '丰', 'symbol': '䷶', 'binary': '101100', 'upper': 'Chấn', 'lower': 'Ly', 'upper_el': 'Mộc', 'lower_el': 'Hỏa', 'quai_tu_zh': '亨，王假之；勿忧，宜日中。', 'quai_tu_vn': 'Hanh, vương cách chi — Phong phú, cực thịnh', 'thoan_truyen_zh': '丰，大也。明以动，故丰。“王假之”，尚大也；“勿忧，宜日中”，宜照天下也。日中则昃，月盈则食；天地盈虚，与时消息，而况人于人乎？况于鬼神乎？', 'dai_tuong_zh': '雷电皆至，丰。君子以折狱致刑。', 'dai_tuong_vn': 'Sấm điện cùng đến, quân tử chiết ngục trí hình', 'y_nghia_vn': 'Phong phú, thịnh vượng, cực thịnh nhưng sẽ suy', 'loi_khuyen_vn': 'Tận hưởng thịnh vượng nhưng biết rằng sẽ suy, chuẩn bị', 'cat_hung': 'CÁT', 'tap_quai_zh': '多故也', 'tu_quai_zh': '得其所歸者必大，豐者大也', 'gaodao_zh': "丰卦象征丰盛繁荣，震雷遇离火。'丰亨，王假之勿忧宜日中'，丰大也，宜照天下。问事事业繁荣，运势亨通。", 'gaodao_en': 'Abundance—supreme success. Thunder and lightning unite, creating great illumination. This hexagram indicates a time of fullness and prosperity when clarity and action unite. Do not worry—maintain this peak period like the sun at noon. Prepare for the natural cycle of decrease that follows abundance.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Hỏa Sơn Lữ': {'id': 56, 'vn_name': 'Hỏa Sơn Lữ', 'zh_name': '旅', 'symbol': '䷷', 'binary': '001101', 'upper': 'Ly', 'lower': 'Cấn', 'upper_el': 'Hỏa', 'lower_el': 'Thổ', 'quai_tu_zh': '小亨，旅贞吉。', 'quai_tu_vn': 'Tiểu hanh, lữ trinh cát — Lữ hành, dừng chân ngắn', 'thoan_truyen_zh': '“旅，小亨”，柔得中乎外而顺乎刚，止而丽乎明，是以“小亨，旅贞吉”也。旅之时义大矣哉！', 'dai_tuong_zh': '山上有火，旅。君子以明慎用刑而不留狱。', 'dai_tuong_vn': 'Trên núi có lửa, quân tử minh thận dụng hình', 'y_nghia_vn': 'Lữ hành, tạm thời, không ổn định, du lịch', 'loi_khuyen_vn': 'Khiêm tốn khi ở nơi lạ, đừng kiêu ngạo, linh hoạt', 'cat_hung': 'BÌNH', 'tap_quai_zh': '親寡也', 'tu_quai_zh': '窮大者必失其居', 'gaodao_zh': "旅卦象征行旅漂泊，离火照艮山。'旅小亨旅贞吉'，旅之时义大矣哉，慎用刑而不用狱。问事有变动之象，宜外出发展。", 'gaodao_en': 'The Wanderer—small success through perseverance. Fire on the mountain illuminates but does not remain. This hexagram indicates a time of being a stranger in strange lands. Success comes through maintaining correct behavior, careful use of resources, and respect for local customs while traveling or in transition.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Tốn Vi Phong': {'id': 57, 'vn_name': 'Tốn Vi Phong', 'zh_name': '巽', 'symbol': '䷸', 'binary': '011011', 'upper': 'Tốn', 'lower': 'Tốn', 'upper_el': 'Mộc', 'lower_el': 'Mộc', 'quai_tu_zh': '小亨，利有攸往，利见大人。', 'quai_tu_vn': 'Tiểu hanh, lợi hữu du vãng — Gió thuận thâm nhập', 'thoan_truyen_zh': '重巽以申命。刚巽乎中正而志行，柔皆顺乎刚，是以“小亨，利有攸往，利见大人”。', 'dai_tuong_zh': '随风，巽。君子以申命行事。', 'dai_tuong_vn': 'Gió theo nhau, quân tử thân mệnh hành sự', 'y_nghia_vn': 'Thuận, thâm nhập, nhẹ nhàng, buôn bán', 'loi_khuyen_vn': 'Khiêm nhường thâm nhập, dần dần tiến, linh hoạt', 'cat_hung': 'CÁT', 'tap_quai_zh': '伏也', 'tu_quai_zh': '旅而無所容，巽者入也', 'gaodao_zh': "巽卦象征顺从进入，巽风相重。'巽小亨，利有攸往利见大人'，随风巽君子以申命行事。问事宜柔顺行事，循序渐进。", 'gaodao_en': 'The Gentle—small success through penetration. Wind follows wind, penetrating everywhere. This hexagram indicates the power of gentle, persistent influence. The superior person spreads their commands through gentle, repeated instruction. Success comes through gradual, flexible advance rather than force.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Đoài Vi Trạch': {'id': 58, 'vn_name': 'Đoài Vi Trạch', 'zh_name': '兑', 'symbol': '䷹', 'binary': '110110', 'upper': 'Đoài', 'lower': 'Đoài', 'upper_el': 'Kim', 'lower_el': 'Kim', 'quai_tu_zh': '亨，利贞。', 'quai_tu_vn': 'Hanh, lợi trinh — Vui vẻ, hòa hợp', 'thoan_truyen_zh': '兑，说也。刚中而柔外，说以利贞，是以顺乎天而应乎人。说以先民，民忘其劳；说以犯难，民忘其死；说之大，民劝矣哉！', 'dai_tuong_zh': '丽泽，兑。君子以朋友讲习。', 'dai_tuong_vn': 'Đầm liền nhau, quân tử bằng hữu giảng tập', 'y_nghia_vn': 'Vui vẻ, trao đổi, giao tiếp, hưởng thụ', 'loi_khuyen_vn': 'Giao tiếp cởi mở, vui vẻ chia sẻ, trao đổi bàn bạc', 'cat_hung': 'CÁT', 'tap_quai_zh': '見也', 'tu_quai_zh': '入而後說之，兌者說也', 'gaodao_zh': "兑卦象征和悦喜悦，泽水相重。'兑亨利贞'，刚中而柔外，说以利贞。兑为少女，柔和外悦，朋友讲习互相滋益。问事人际关系和谐，心情愉悦。", 'gaodao_en': 'The Joyous—success through sincere joy. The lake doubles itself, reflecting and multiplying happiness. This hexagram indicates benefits through open, cheerful communication and mutual learning among friends. Joy based on proper principles brings lasting benefit.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Phong Thủy Hoán': {'id': 59, 'vn_name': 'Phong Thủy Hoán', 'zh_name': '涣', 'symbol': '䷺', 'binary': '010011', 'upper': 'Tốn', 'lower': 'Khảm', 'upper_el': 'Mộc', 'lower_el': 'Thủy', 'quai_tu_zh': '亨，王假有庙，利涉大川，利贞。', 'quai_tu_vn': 'Hanh, vương cách hữu miếu — Tan rã rồi hội tụ', 'thoan_truyen_zh': '“涣，亨”，刚来而不穷，柔得位乎外而上同。“王假有庙”，王乃在中也。“利涉大川”，乘木有功也。', 'dai_tuong_zh': '风行水上，涣。先王以享于帝，立庙。', 'dai_tuong_vn': 'Gió trên nước, tiên vương hưởng vu đế lập miếu', 'y_nghia_vn': 'Phân tán, tan rã, rồi tập hợp lại, lưu thông', 'loi_khuyen_vn': 'Phá bỏ rào cản, tập hợp lại sau phân tán', 'cat_hung': 'BÌNH', 'tap_quai_zh': '離也', 'tu_quai_zh': '說而後散之，渙者離也', 'gaodao_zh': "涣卦象征涣散化解，坎水入巽风。'涣亨，王假有庙利涉大川'。问事困难将化解，前景好转。聚者散之，涣者聚之。", 'gaodao_en': 'Dispersion—success through dissolution. Wind over water disperses ice and rigidity. This hexagram indicates a time when rigidity dissolves and obstacles disperse. The king approaches the temple—reconnecting with source and spirit helps dissolve difficulties. Crossing great waters is beneficial.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Thủy Trạch Tiết': {'id': 60, 'vn_name': 'Thủy Trạch Tiết', 'zh_name': '节', 'symbol': '䷻', 'binary': '110010', 'upper': 'Khảm', 'lower': 'Đoài', 'upper_el': 'Thủy', 'lower_el': 'Kim', 'quai_tu_zh': '亨，苦节，不可贞。', 'quai_tu_vn': 'Hanh, khổ tiết bất khả trinh — Tiết chế, điều độ', 'thoan_truyen_zh': '“节，亨”，刚柔分而刚得中。“苦节，不可贞”，其道穷也。说以行险，当位以节，中正以通。天地节而四时成；节以制度，不伤财，不害民。', 'dai_tuong_zh': '泽上有水，节。君子以制数度，议德行。', 'dai_tuong_vn': 'Trên đầm có nước, quân tử chế số độ nghị đức hạnh', 'y_nghia_vn': 'Tiết chế, điều độ, giới hạn, kỷ luật', 'loi_khuyen_vn': 'Giữ điều độ, tiết chế chi tiêu và hành vi', 'cat_hung': 'CÁT', 'tap_quai_zh': '止也', 'tu_quai_zh': '物不可以終離', 'gaodao_zh': "节卦象征节制适度，兑泽下临坎水。'节亨，苦节不可贞'，节以制度不伤财不害民。问事宜节制行事，不可过度。", 'gaodao_en': 'Limitation—success through restraint. Water over the lake—regulating the flow. This hexagram indicates the necessity of proper limits and boundaries. Not too much, not too little. Limitation through proper institutions brings benefit without causing damage or regret.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Phong Trạch Trung Phu': {'id': 61, 'vn_name': 'Phong Trạch Trung Phu', 'zh_name': '中孚', 'symbol': '䷼', 'binary': '110011', 'upper': 'Tốn', 'lower': 'Đoài', 'upper_el': 'Mộc', 'lower_el': 'Kim', 'quai_tu_zh': '豚鱼吉，利涉大川，利贞。', 'quai_tu_vn': 'Đồn ngư cát, lợi thiệp đại xuyên — Lòng thành cảm hóa', 'thoan_truyen_zh': '“中孚”，柔在内而刚得中。说而巽，孚乃化邦也。“豚鱼吉”，信及豚鱼也：“利涉大川”，乘木舟虚也。中孚以“利贞”，乃应乎天也。', 'dai_tuong_zh': '泽上有风，中孚。君子以议狱缓死。', 'dai_tuong_vn': 'Trên đầm có gió, quân tử nghị ngục hoãn tử', 'y_nghia_vn': 'Trung thành, tin tưởng, lòng thành, cảm hóa', 'loi_khuyen_vn': 'Giữ lòng thành, tin tưởng lẫn nhau, cảm hóa người', 'cat_hung': 'CÁT', 'tap_quai_zh': '信也', 'tu_quai_zh': '節而信之', 'gaodao_zh': "中孚卦象征诚信忠实，兑泽上有巽风。'中孚豚鱼吉，利涉大川利贞'。诚信为本，感而遂通。问事以诚信为本，可得信任。", 'gaodao_en': 'Inner Truth—success through sincerity. Wind over the lake penetrates everywhere. This hexagram indicates the power of genuine, heartfelt truth that can even affect fish and pigs. Sincerity creates the conditions for crossing great waters. Trust and openness bring lasting benefit.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Lôi Sơn Tiểu Quá': {'id': 62, 'vn_name': 'Lôi Sơn Tiểu Quá', 'zh_name': '小过', 'symbol': '䷽', 'binary': '001100', 'upper': 'Chấn', 'lower': 'Cấn', 'upper_el': 'Mộc', 'lower_el': 'Thổ', 'quai_tu_zh': '亨，利贞；可小事，不可大事；飞鸟遗之音，不宜上，宜下，大吉。', 'quai_tu_vn': 'Hanh lợi trinh, khả tiểu sự — Vượt nhỏ, làm việc nhỏ tốt', 'thoan_truyen_zh': '小过，小者过而亨也。过以“利贞”，与时行也。柔得中，是以“小事吉”也。刚失位而不中，是以“不可大事”也。有“飞鸟”之象焉，“飞鸟遗之音，不宜上，宜下，大吉”，上逆而下顺也。', 'dai_tuong_zh': '山上有雷，小过。君子以行过乎恭，丧过乎哀，用过乎俭。', 'dai_tuong_vn': 'Trên núi có sấm, quân tử hành quá cung, tang quá ai', 'y_nghia_vn': 'Vượt qua nhỏ, làm việc nhỏ, khiêm tốn hạ mình', 'loi_khuyen_vn': 'Chỉ làm việc nhỏ, đừng tham lam, khiêm tốn', 'cat_hung': 'BÌNH', 'tap_quai_zh': '過也', 'tu_quai_zh': '有其信者必行之', 'gaodao_zh': "小过卦象征小有过越，艮山止震雷。'小过亨利贞，可小事不可大事'。飞鸟遗之音，不宜上宜下。问事有小波折，但无大碍。", 'gaodao_en': 'Preponderance of the Small—success through humility in small matters. Thunder on the mountain—small excess. This hexagram advises attending to small things while avoiding great undertakings. Like a bird in flight leaving its call, do not try to soar too high. Success comes through modest aims and attention to detail.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Thủy Hỏa Ký Tế': {'id': 63, 'vn_name': 'Thủy Hỏa Ký Tế', 'zh_name': '既济', 'symbol': '䷾', 'binary': '101010', 'upper': 'Khảm', 'lower': 'Ly', 'upper_el': 'Thủy', 'lower_el': 'Hỏa', 'quai_tu_zh': '亨小，利贞。初吉终乱。', 'quai_tu_vn': 'Hanh tiểu, lợi trinh, sơ cát chung loạn — Đã xong việc', 'thoan_truyen_zh': '“既济，亨”，小者亨也。“利贞”，刚柔正而位当也。“初吉”，柔得中也。终止则乱，其道穷也。', 'dai_tuong_zh': '水在火上，既济。君子以思患而豫防之。', 'dai_tuong_vn': 'Nước trên lửa, quân tử tư hoạn nhi dự phòng', 'y_nghia_vn': 'Đã hoàn thành, mọi việc đâu vào đấy, nhưng cần phòng suy', 'loi_khuyen_vn': 'Cẩn thận sau thành công, phòng ngừa suy thoái', 'cat_hung': 'CÁT', 'tap_quai_zh': '定也', 'tu_quai_zh': '有過物者必濟', 'gaodao_zh': "既济卦象征事已成功，离火上照坎水。'既济亨，小利贞初吉终乱'。成功之后戒慎恐惧，思患豫防方保终吉。", 'gaodao_en': 'After Completion—success in small matters. Water over fire completes the cooking. This hexagram indicates a time when things are complete and successful, but this very completion contains the seeds of new disorder. Guard against complacency; maintain vigilance even after success.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}, 'Hỏa Thủy Vị Tế': {'id': 64, 'vn_name': 'Hỏa Thủy Vị Tế', 'zh_name': '未济', 'symbol': '䷿', 'binary': '010101', 'upper': 'Ly', 'lower': 'Khảm', 'upper_el': 'Hỏa', 'lower_el': 'Thủy', 'quai_tu_zh': '亨，小狐汔济，濡其尾，无攸利。', 'quai_tu_vn': 'Hanh, tiểu hồ kỷ tế — Chưa hoàn thành, còn tiếp tục', 'thoan_truyen_zh': '“未济，亨”，柔得中也。“小狐汔济”，未出中也；“濡其尾，无攸利”，不续终也。虽不当位，刚柔应也。', 'dai_tuong_zh': '火在水上，未济。君子以慎辨物居方。', 'dai_tuong_vn': 'Lửa trên nước, quân tử thận biện vật cư phương', 'y_nghia_vn': 'Chưa hoàn thành, vẫn tiếp tục, tiềm năng phía trước', 'loi_khuyen_vn': 'Kiên nhẫn hoàn thành, đừng bỏ cuộc, vẫn còn cơ hội', 'cat_hung': 'BÌNH', 'tap_quai_zh': '男之窮也', 'tu_quai_zh': '物不可窮也，終焉', 'gaodao_zh': "未济卦象征事未成功，离火上浮。'未济亨，柔得中也'，小狐汔济未出中。问事需继续努力，终有成之机。思患豫防。", 'gaodao_en': 'Before Completion—success through continued effort. Fire rises over water, not yet completing its work. This hexagram indicates a time when the goal is in sight but not yet reached. Success comes through maintaining care and foresight to the very end, preventing complacency before completion.', 'topics_vn': {'fortune': 'Bình', 'wish': '', 'love': '', 'family': '', 'sickness': '', 'lost_item': '', 'career': ''}}}

