def normalize_hex_name(name: str) -> str:
    s = str(name or '').strip()
    if s in ZHOUYI_64_FULL:
        return s
    if s in BAT_THUAN_ALIAS_MAP:
        return BAT_THUAN_ALIAS_MAP[s]
    s_vi = s.replace(' vi ', ' Vi ')
    if s_vi in ZHOUYI_64_FULL:
        return s_vi
    for k in ZHOUYI_64_FULL:
        if k.lower() == s.lower():
            return k
    return s


def get_zhouyi_hexagram(name: str) -> dict:
    canon = normalize_hex_name(name)
    return ZHOUYI_64_FULL.get(canon, {})


def get_zhouyi_line(name: str, pos: int) -> dict:
    canon = normalize_hex_name(name)
    try:
        p = int(pos)
    except Exception:
        p = 1
    p = max(1, min(6, p))
    return ZHOUYI_384_LINES.get((canon, p), {})
